import type { BankQuestion } from "@/lib/bank";

/** Financial & Cost Accounting (Management & Commerce): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-accounting-1","question":"A trader starts business with cash ₹5,00,000, buys goods for ₹1,20,000 on credit and sells goods costing ₹40,000 for ₹55,000 in cash. What are the total assets after these transactions?","options":["₹6,20,000","₹6,35,000","₹6,75,000","₹5,15,000"],"answer":1,"explanation":"Cash = 5,00,000 + 55,000 = ₹5,55,000; stock = 1,20,000 − 40,000 = ₹80,000. Total assets = ₹6,35,000 (= creditors 1,20,000 + capital 5,15,000, the capital including the ₹15,000 profit). ₹6,20,000 ignores the profit and ₹6,75,000 forgets to reduce the stock sold.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-2","question":"Which of these errors will NOT cause the trial balance to disagree?","options":["The sales book is overcast by ₹2,000","A debit of ₹500 is posted to the credit side of a supplier's account","Machinery bought for ₹50,000 is debited to the Purchases account","A sales invoice of ₹3,000 is posted to the Sales account but not to the customer's account"],"answer":2,"explanation":"Debiting machinery to Purchases is an error of principle: the debit is still a debit of the right amount, so the totals agree. The other three are one-sided errors that change only one side of the trial balance.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-3","question":"After a suspense account has been opened, it is found that the sales book was undercast by ₹2,000. What is the rectifying entry?","options":["Sales A/c Dr ₹2,000 To Suspense A/c ₹2,000","Debtors A/c Dr ₹2,000 To Sales A/c ₹2,000","Suspense A/c Dr ₹2,000 To Sales A/c ₹2,000","No entry is needed because the debtors were posted correctly"],"answer":2,"explanation":"Undercasting the sales book means the Sales account was credited ₹2,000 too little, while the individual debtors were debited correctly. Only the Sales account needs a further credit, and the other side goes to Suspense: Suspense Dr, Sales Cr.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-4","question":"A trial balance does not agree and the difference is put in a suspense account. The only errors are: (a) the purchase returns book was overcast by ₹1,000; (b) salary of ₹2,500 was posted to the Salary account as ₹5,200; (c) discount allowed of ₹400 was not posted to the Discount account. What was the suspense account balance?","options":["₹1,300 debit","₹4,100 credit","₹3,300 debit","₹1,300 credit"],"answer":3,"explanation":"(a) Credit side too high by ₹1,000. (b) Debit side too high by ₹2,700. (c) Debit side too low by ₹400. Net: debits exceed credits by 2,700 − 400 − 1,000 = ₹1,300, so the suspense account needed a credit of ₹1,300 to make the totals agree.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-5","question":"A machine is bought on 1 July 2022 for ₹4,80,000 and ₹20,000 is spent on installing it. Residual value is ₹50,000 and useful life 9 years. With the financial year ending 31 March and straight-line depreciation, what is the charge for 2022-23?","options":["₹37,500","₹50,000","₹41,667","₹35,833"],"answer":0,"explanation":"Cost = 4,80,000 + 20,000 = ₹5,00,000 (installation is capitalised). Annual charge = (5,00,000 − 50,000) ÷ 9 = ₹50,000. For 9 months (July to March): 50,000 × 9/12 = ₹37,500. ₹35,833 leaves out installation; ₹50,000 ignores time.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-6","question":"An asset bought on 1 April 2021 for ₹8,00,000 is depreciated at 20% a year on the written-down value. It is sold on 30 September 2023 for ₹4,50,000. What is the profit or loss on sale (year ends 31 March)?","options":["Loss ₹62,000","Profit ₹40,400","Loss ₹10,800","Profit ₹10,800"],"answer":2,"explanation":"Book value on 31 Mar 2022 = 6,40,000; on 31 Mar 2023 = 5,12,000. Depreciation for April–September 2023 = 5,12,000 × 20% × 6/12 = 51,200, so book value at sale = ₹4,60,800. Loss = 4,60,800 − 4,50,000 = ₹10,800. Skipping the half-year charge gives a ₹62,000 loss; charging a full year gives a ₹40,400 profit.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-7","question":"An asset costs ₹2,00,000. What is the difference between total depreciation over the first three years at 10% straight-line on cost and at 10% on the written-down value?","options":["₹6,000","₹5,800","₹4,200","₹5,420"],"answer":1,"explanation":"SLM: 20,000 × 3 = ₹60,000. WDV: 20,000 + 18,000 + 16,200 = ₹54,200. Difference = ₹5,800.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-8","question":"A machine costing ₹6,40,000 is expected to be worth ₹2,70,000 after 3 years. What written-down-value rate writes it down to exactly that amount?","options":["19.27%","20%","30%","25%"],"answer":3,"explanation":"(1 − r)³ = 2,70,000 ÷ 6,40,000 = 27/64, so 1 − r = 3/4 and r = 25%. Check: 6,40,000 → 4,80,000 → 3,60,000 → 2,70,000. 19.27% is the straight-line rate on cost, (6,40,000 − 2,70,000) ÷ 3 ÷ 6,40,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-9","question":"Machinery costing ₹6,00,000 was bought on 1 April 2021. A new machine costing ₹2,00,000 is bought on 1 October 2023, and on 1 January 2024 one of the original machines (cost ₹1,00,000) is sold. Depreciation is 10% straight-line on cost. What is the total depreciation for 2023-24 (year ending 31 March)?","options":["₹70,000","₹60,000","₹67,500","₹77,500"],"answer":2,"explanation":"Remaining old machines: 5,00,000 × 10% = ₹50,000. Machine sold: 1,00,000 × 10% × 9/12 = ₹7,500. New machine: 2,00,000 × 10% × 6/12 = ₹10,000. Total = ₹67,500. ₹77,500 charges the full ₹60,000 on the old block and then adds the sold machine again.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-10","question":"A machine costing ₹1,00,000 was bought on 1 April 2021 and is depreciated at 10% straight-line on cost (year ends 31 March). It is sold on 1 January 2024 for ₹70,000. What is the result of the sale?","options":["Loss ₹10,000","Loss ₹2,500","Neither profit nor loss","Profit ₹2,500"],"answer":1,"explanation":"Depreciation: 2021-22 ₹10,000, 2022-23 ₹10,000, 1 Apr–31 Dec 2023 ₹7,500 → accumulated ₹27,500, book value ₹72,500. Sale at ₹70,000 gives a loss of ₹2,500. Ignoring the current-year charge gives a ₹10,000 loss; charging a full year gives no profit or loss.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-11","question":"Which of these are capital expenditure? (i) Wages paid to the firm's own workers for installing a new machine (ii) Replacing the worn-out tyres of a delivery van (iii) Overhauling a second-hand truck immediately after buying it, before first use (iv) Extending the factory building to raise capacity (v) Annual maintenance contract fee","options":["(i) and (iv) only","(i), (iii) and (iv) only","(i), (ii), (iii) and (iv)","(iii) and (iv) only"],"answer":1,"explanation":"Installation wages and overhaul needed to bring a newly bought asset into use are part of its cost; an extension raises capacity. Replacing worn tyres and AMC fees only maintain the asset, so they are revenue expenditure.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-12","question":"Valuing closing stock at the lower of cost and net realisable value follows which accounting concept?","options":["Prudence (conservatism)","Matching","Going concern","Money measurement"],"answer":0,"explanation":"Prudence: provide for expected losses but do not anticipate gains, so stock is written down when its NRV falls below cost.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-13","question":"Closing stock consists of Item A (cost ₹50,000, NRV ₹60,000) and Item B (cost ₹70,000, NRV ₹45,000). At what amount should it appear in the balance sheet under Ind AS 2?","options":["₹1,05,000","₹1,20,000","₹95,000","₹1,10,000"],"answer":2,"explanation":"Ind AS 2 applies the lower of cost and NRV item by item: A at ₹50,000 (cost), B at ₹45,000 (NRV) = ₹95,000. Comparing the totals (₹1,20,000 vs ₹1,05,000) lets A's unrealised gain offset B's loss, which the standard does not allow.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-14","question":"A credit sale of ₹7,500 to Ravi was entered in the purchases book and posted from there. What is the effect on gross profit?","options":["Understated by ₹7,500","Overstated by ₹7,500","No effect","Understated by ₹15,000"],"answer":3,"explanation":"Sales are understated by ₹7,500 and purchases overstated by ₹7,500; both reduce gross profit, so it is understated by ₹15,000. (Ravi's account is also credited instead of debited, a ₹15,000 swing on his balance.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-15","question":"Goods of ₹6,000 taken by the proprietor for personal use last year were never recorded. The books for last year are closed. What entry rectifies this in the current year?","options":["Drawings A/c Dr To Purchases A/c ₹6,000","Drawings A/c Dr To Profit & Loss Adjustment A/c ₹6,000","Purchases A/c Dr To Drawings A/c ₹6,000","Capital A/c Dr To Suspense A/c ₹6,000"],"answer":1,"explanation":"Last year's purchases were overstated (profit understated). The Purchases account is closed, so the nominal-account side goes to a Profit & Loss Adjustment account: Drawings Dr, P&L Adjustment Cr ₹6,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-16","question":"Net profit before finding these errors is ₹1,50,000: (a) furniture of ₹12,000 bought at the start of the year was debited to Purchases (depreciation on furniture is 10%); (b) the sales returns book was overcast by ₹1,500; (c) rent of ₹4,000 paid was debited to the landlord's personal account. What is the corrected net profit?","options":["₹1,59,500","₹1,58,300","₹1,66,300","₹1,55,300"],"answer":1,"explanation":"(a) +12,000 for the wrong expense, −1,200 depreciation. (b) Returns were overstated, so sales were cut too much: +1,500. (c) Rent expense was missing: −4,000. 1,50,000 + 12,000 − 1,200 + 1,500 − 4,000 = ₹1,58,300.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-17","question":"Which of these normally has a credit balance in a trial balance?","options":["Drawings","Provision for doubtful debts","Discount allowed","Prepaid insurance"],"answer":1,"explanation":"A provision for doubtful debts is a credit balance deducted from debtors. Drawings, discount allowed (an expense) and prepaid insurance (an asset) are debit balances.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-18","question":"Under Ind AS 16 and Ind AS 8, how is a change from the written-down-value method to the straight-line method of depreciation treated?","options":["As a change in accounting policy, applied retrospectively","As a prior-period error, restated in comparatives","As a change in accounting estimate, applied prospectively","It is not allowed once a method has been chosen"],"answer":2,"explanation":"The depreciation method reflects the expected pattern of using up the asset's benefits, so a change in method is a change in accounting estimate and is applied prospectively from the date of change.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-19","question":"A machine bought on 1 April 2021 for ₹10,00,000 is depreciated straight-line over 10 years with nil residual value. On 1 April 2024 the remaining life is revised to 5 years and the residual value to ₹50,000. What is the depreciation for 2024-25?","options":["₹1,30,000","₹1,00,000","₹1,40,000","₹1,90,000"],"answer":0,"explanation":"Book value on 1 April 2024 = 10,00,000 − 3 × 1,00,000 = ₹7,00,000. Revised charge = (7,00,000 − 50,000) ÷ 5 = ₹1,30,000, applied prospectively. ₹1,40,000 ignores the residual value; ₹1,90,000 restarts from cost.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-20","question":"Goods costing ₹10,000 are given away as charity. What is the journal entry?","options":["Charity A/c Dr To Sales A/c","Charity A/c Dr To Purchases A/c","Purchases A/c Dr To Charity A/c","Charity A/c Dr To Cash A/c"],"answer":1,"explanation":"The goods leave at cost and were never sold, so Purchases is credited (reduced) and Charity, an expense, is debited.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-21","question":"₹19,600 is paid to a creditor in full settlement of ₹20,000. What is the correct entry?","options":["Creditor Dr ₹19,600 To Cash ₹19,600","Creditor Dr ₹20,000 To Cash ₹19,600, To Discount Allowed ₹400","Creditor Dr ₹20,000 To Cash ₹19,600, To Discount Received ₹400","Creditor Dr ₹19,600, Discount Received Dr ₹400 To Cash ₹20,000"],"answer":2,"explanation":"The whole ₹20,000 liability is cleared, ₹19,600 in cash; the ₹400 saved is a gain, credited to Discount Received.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-22","question":"Old furniture with a book value of ₹8,000 was sold for ₹6,000 and the proceeds were credited to the Sales account. By how much is the net profit overstated?","options":["₹6,000","₹2,000","₹8,000","It is understated by ₹2,000"],"answer":2,"explanation":"Reported profit includes ₹6,000 as sales. Correctly, the sale should show a loss of ₹2,000 (6,000 − 8,000). The gap is 6,000 − (−2,000) = ₹8,000 overstated; the furniture also stays in the books at ₹8,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-23","question":"A proprietor keeps incomplete records. Capital was ₹4,00,000 at the start of the year and ₹5,10,000 at the end. He withdrew ₹9,000 a month in cash and took goods worth ₹12,000 for personal use; he also introduced fresh capital of ₹50,000. What is the profit for the year?","options":["₹1,68,000","₹2,80,000","₹1,80,000","₹60,000"],"answer":2,"explanation":"Profit = closing capital − opening capital + drawings − fresh capital = 5,10,000 − 4,00,000 + (1,08,000 + 12,000) − 50,000 = ₹1,80,000. Forgetting the goods gives ₹1,68,000; adding the fresh capital gives ₹2,80,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-24","question":"An asset costing ₹2,00,000 with a residual value of ₹20,000 is depreciated straight-line at ₹36,000 a year. What useful life has been assumed?","options":["5.56 years","4.5 years","5 years","6 years"],"answer":2,"explanation":"Life = (cost − residual) ÷ annual charge = 1,80,000 ÷ 36,000 = 5 years. 5.56 years wrongly divides the full cost.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-25","question":"A machine costing ₹12,00,000 (residual value ₹2,00,000) is expected to run 50,000 hours. It runs 8,000 hours in year 1 and 12,000 hours in year 2. What is the year-2 charge under the units-of-production method?","options":["₹2,88,000","₹2,40,000","₹1,60,000","₹2,00,000"],"answer":1,"explanation":"Rate = (12,00,000 − 2,00,000) ÷ 50,000 = ₹20 per hour. Year 2 = 12,000 × 20 = ₹2,40,000. ₹2,88,000 ignores the residual value.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-26","question":"A firm charges 10% depreciation on the written-down value, crediting it directly to the asset account. It bought a machine for ₹5,00,000 on 1 April 2022 and another for ₹2,00,000 on 1 October 2022. What is the machinery account balance on 31 March 2024?","options":["₹5,67,000","₹5,70,000","₹5,60,000","₹5,76,000"],"answer":3,"explanation":"Machine 1: 5,00,000 × 0.9 × 0.9 = ₹4,05,000. Machine 2: half-year in 2022-23, 2,00,000 − 10,000 = 1,90,000; then 1,90,000 − 19,000 = ₹1,71,000. Total ₹5,76,000. Charging machine 2 a full first year gives ₹5,67,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-27","question":"Assertion (A): A company cannot capitalise a large advertising campaign even if it expects the campaign to bring sales for three years. Reason (R): Ind AS 38 requires spending on advertising and promotional activities to be recognised as an expense when incurred.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Ind AS 38 specifically lists advertising and promotional spending as an expense when incurred, because it does not create an identifiable intangible asset the entity controls. That is exactly why A holds.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-28","question":"Which of these costs is included in the cost of inventory under Ind AS 2?","options":["Abnormal wastage of materials","Selling and distribution costs","Freight inward on raw materials","Storage of finished goods awaiting sale"],"answer":2,"explanation":"Costs of purchase, including freight inward, are part of inventory cost. Abnormal wastage, selling costs and storage costs (unless storage is necessary in the production process) are expensed.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-29","question":"Assertion (A): A revaluation decrease on an asset that carries an earlier revaluation surplus is first set off against that surplus. Reason (R): Under Ind AS 16, every revaluation decrease is recognised in profit or loss.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":3,"explanation":"A decrease is first debited to OCI to the extent of any surplus held for that same asset; only the excess goes to profit or loss. So A is true and R, which says 'every decrease goes to P&L', is false.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-30","question":"Which of these is a nominal account?","options":["Capital","Commission received","Debtors","Machinery"],"answer":1,"explanation":"Nominal accounts record incomes, expenses, gains and losses; commission received is an income. Capital and debtors are personal accounts and machinery is a real account.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-31","question":"The cash book shows a debit balance of ₹25,000. Cheques of ₹4,000 issued to suppliers have not yet been presented. If there is no other difference, what does the pass book show?","options":["₹29,000","₹21,000","₹25,000","₹33,000"],"answer":0,"explanation":"The cash book has already deducted the ₹4,000, but the bank has not paid it yet, so the bank balance is higher: 25,000 + 4,000 = ₹29,000.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-32","question":"The cash book shows a debit balance of ₹48,000. Cheques deposited ₹12,000 are not yet cleared; cheques issued ₹7,500 are not yet presented; bank charges ₹300 and interest credited ₹1,200 are not in the cash book; a customer paid ₹5,000 directly into the bank. What is the pass-book balance?","options":["₹58,400","₹44,400","₹46,600","₹49,400"],"answer":3,"explanation":"48,000 − 12,000 (deposits not cleared) + 7,500 (cheques not presented) − 300 + 1,200 + 5,000 = ₹49,400. Swapping the treatment of the two cheque items gives ₹58,400; missing the direct deposit gives ₹44,400.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-33","question":"The pass book shows an overdraft of ₹30,000. Cheques issued ₹8,000 are not yet presented, cheques deposited ₹5,000 are not yet credited, and bank charges of ₹600 appear only in the pass book. What is the cash-book balance?","options":["Overdraft ₹32,400","Overdraft ₹27,600","Overdraft ₹23,400","Overdraft ₹36,600"],"answer":0,"explanation":"Work from −30,000: the cash book has already paid the ₹8,000 (−8,000), already received the ₹5,000 (+5,000) and not yet deducted the ₹600 charges (+600): −30,000 − 8,000 + 5,000 + 600 = −32,400, an overdraft of ₹32,400.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-34","question":"The trial balance shows debtors ₹2,10,000, bad debts ₹4,000 and a provision for doubtful debts of ₹8,000. Adjustments: write off further bad debts of ₹10,000 and keep the provision at 5% of debtors. What is the total charge to the profit and loss account for bad and doubtful debts?","options":["₹6,000","₹12,500","₹24,000","₹16,000"],"answer":3,"explanation":"Bad debts = 4,000 + 10,000 = 14,000. New provision = 5% × (2,10,000 − 10,000) = 10,000; increase over the old ₹8,000 = 2,000. Charge = 14,000 + 2,000 = ₹16,000. ₹12,500 takes 5% on debtors before the write-off.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-35","question":"Debtors stand at ₹2,10,000. Further bad debts of ₹10,000 are written off, a 5% provision for doubtful debts is made and then a 2% provision for discount on debtors. At what net amount are debtors shown in the balance sheet?","options":["₹1,86,200","₹1,86,000","₹1,90,000","₹1,95,310"],"answer":0,"explanation":"2,10,000 − 10,000 = 2,00,000; doubtful-debt provision 10,000 → 1,90,000; discount provision 2% of the good debts 1,90,000 = 3,800 → ₹1,86,200. Taking 2% of ₹2,00,000 gives ₹1,86,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-36","question":"Wages paid during the year are ₹84,000, which includes ₹6,000 outstanding from the previous year. Wages of ₹9,000 are outstanding at the year end. What amount is charged for wages this year?","options":["₹93,000","₹81,000","₹99,000","₹87,000"],"answer":3,"explanation":"84,000 − 6,000 (belongs to last year) + 9,000 (this year's unpaid) = ₹87,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-37","question":"An annual insurance premium of ₹36,000 is paid on 1 August 2023. The accounts close on 31 March 2024. What is the prepaid insurance in the balance sheet?","options":["₹12,000","₹24,000","₹9,000","₹15,000"],"answer":0,"explanation":"The premium covers August 2023 to July 2024; April–July 2024 (4 months) lies in the next year: 36,000 × 4/12 = ₹12,000. ₹24,000 is this year's expense.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-38","question":"Net profit before the manager's commission is ₹2,20,000. The manager gets 10% of the net profit after charging his commission. What is his commission?","options":["₹20,000","₹22,000","₹24,200","₹18,000"],"answer":0,"explanation":"If commission = C, C = 10% × (2,20,000 − C), so 1.1C = 22,000 and C = ₹20,000 (= 2,20,000 × 10/110). ₹22,000 is 10% before commission.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-39","question":"Goods costing ₹50,000 are destroyed by fire and the insurer admits a claim of ₹35,000, still unpaid at the year end. Which treatment is correct?","options":["Debit P&L ₹50,000 and credit Trading ₹50,000; record the claim only when cash is received","Debit Trading ₹15,000 and make no other entry","Reduce closing stock by ₹50,000 and make no other entry","Credit Trading ₹50,000; debit Insurance Claim Receivable ₹35,000 and P&L ₹15,000"],"answer":3,"explanation":"The goods are taken out of Trading at cost (credit ₹50,000). The admitted claim is an asset (receivable ₹35,000) even though unpaid, and only the uncovered ₹15,000 is a loss in the P&L. Waiting for cash breaks the accrual concept.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-40","question":"Opening stock ₹60,000, purchases ₹3,40,000, purchase returns ₹10,000, carriage inward ₹15,000, wages ₹25,000, sales ₹5,00,000, sales returns ₹20,000, closing stock ₹80,000. What is the gross profit?","options":["₹1,50,000","₹1,70,000","₹1,20,000","₹1,30,000"],"answer":3,"explanation":"Net sales 4,80,000. Cost of goods sold = 60,000 + 3,30,000 + 15,000 + 25,000 − 80,000 = 3,50,000. Gross profit = ₹1,30,000. Forgetting sales returns gives ₹1,50,000; forgetting purchase returns gives ₹1,20,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-41","question":"Closing stock of ₹80,000 appears inside the trial balance (purchases have already been adjusted for it). Where is it shown in the final accounts?","options":["Only in the balance sheet, as a current asset","On the credit side of the Trading account and in the balance sheet","Only on the credit side of the Trading account","On the debit side of the Trading account"],"answer":0,"explanation":"When closing stock is inside the trial balance, it has already been deducted from purchases (adjusted purchases). Crediting Trading again would count it twice, so it goes only to the balance sheet.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-42","question":"Goods worth ₹12,000 received on the last day of the year are included in closing stock, but the supplier's invoice has not been recorded. What is the effect?","options":["Profit overstated by ₹12,000 and creditors understated by ₹12,000","No effect on profit, because the goods are in stock","Profit understated by ₹12,000","Profit overstated by ₹24,000"],"answer":0,"explanation":"The goods raise closing stock (and profit) by ₹12,000, but the matching purchase is missing. Recording the purchase raises cost of goods sold by ₹12,000 and creates the creditor, so profit was overstated by ₹12,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-43","question":"A trader prices goods at cost plus 20%. Goods sent on approval at ₹24,000 (selling price) were recorded as sales, but the customer has not yet approved them at the year end. What adjustment to profit is needed?","options":["Reduce profit by ₹24,000","Reduce profit by ₹4,800","Increase profit by ₹20,000","Reduce profit by ₹4,000"],"answer":3,"explanation":"Cancel the sale (−24,000) and bring the goods back into closing stock at cost, 24,000 ÷ 1.2 = 20,000 (+20,000). Net reduction = ₹4,000, the profit loaded in the price. 20% of 24,000 (₹4,800) confuses mark-up on cost with margin on sales.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-44","question":"The cash book shows an overdraft of ₹15,000. A cheque of ₹2,000 issued to a supplier was entered twice on the payments side, cheques deposited ₹6,000 are not yet credited, and interest on overdraft ₹900 has been charged only by the bank. What is the pass-book balance?","options":["Overdraft ₹23,900","Overdraft ₹21,900","Overdraft ₹8,100","Overdraft ₹19,900"],"answer":3,"explanation":"Start at −15,000. The duplicate entry overstated payments, so the true position is better: +2,000 → −13,000. Deposits not credited: −6,000 → −19,000. Interest: −900 → −19,900, an overdraft of ₹19,900.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-45","question":"₹1,00,000 is invested in 12% debentures. Interest for only 9 months has been received during the year. What accrued interest is shown at the year end?","options":["₹3,000","₹9,000","₹12,000","₹4,000"],"answer":0,"explanation":"Annual interest = ₹12,000; 9 months (₹9,000) received, so 3 months = ₹3,000 has accrued.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-46","question":"Which item appears on the credit side of the Trading account?","options":["Closing stock","Carriage inward","Wages","Opening stock"],"answer":0,"explanation":"Closing stock (when it is outside the trial balance) is credited to Trading; carriage inward, wages and opening stock are debits.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-47","question":"Opening debtors ₹40,000, closing debtors ₹55,000, cash received from debtors ₹2,60,000, discount allowed ₹5,000, bad debts ₹3,000 and sales returns ₹7,000. What were the credit sales?","options":["₹2,75,000","₹2,80,000","₹2,60,000","₹2,90,000"],"answer":3,"explanation":"Debtors account: credit sales = closing 55,000 + cash 2,60,000 + discount 5,000 + bad debts 3,000 + returns 7,000 − opening 40,000 = ₹2,90,000. Ignoring the three non-cash credits gives ₹2,75,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-48","question":"Opening creditors ₹30,000, closing creditors ₹45,000, cash paid to creditors ₹1,80,000, discount received ₹4,000, purchase returns ₹6,000 and cash purchases ₹20,000. What are the total purchases before deducting returns?","options":["₹2,25,000","₹2,05,000","₹2,19,000","₹2,15,000"],"answer":0,"explanation":"Credit purchases = 45,000 + 1,80,000 + 4,000 + 6,000 − 30,000 = 2,05,000. Total purchases = 2,05,000 + 20,000 cash = ₹2,25,000. ₹2,19,000 is net of returns; ₹2,05,000 forgets the cash purchases.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-49","question":"Sales are ₹6,00,000, opening stock ₹70,000 and purchases ₹4,80,000. Gross profit is 25% of cost. What is the closing stock?","options":["₹1,00,000","₹1,20,000","₹50,000","₹70,000"],"answer":3,"explanation":"Profit is 25% of cost, so cost of goods sold = 6,00,000 ÷ 1.25 = 4,80,000. Closing stock = 70,000 + 4,80,000 − 4,80,000 = ₹70,000. Treating 25% as a margin on sales gives ₹1,00,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-50","question":"A fire destroys stock. Stock on 1 April was ₹80,000; purchases to the date of the fire ₹3,20,000; sales ₹4,50,000; gross profit is 20% of sales. Goods worth ₹10,000 were saved. The stock was insured for ₹24,000 under a policy with an average clause. What is the claim?","options":["₹18,000","₹24,000","₹30,000","₹14,400"],"answer":0,"explanation":"Stock at fire = 80,000 + 3,20,000 − (4,50,000 × 80%) = ₹40,000. Loss = 40,000 − 10,000 = ₹30,000. Under-insured, so claim = 30,000 × 24,000/40,000 = ₹18,000. Using 20% on cost gives ₹14,400.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-51","question":"Which year-end transaction affects only the balance sheet, not the profit for the year?","options":["Salaries outstanding","Depreciation on machinery","Commission accrued but not received","Machinery bought for cash on the last day of the year"],"answer":3,"explanation":"Buying an asset for cash swaps one asset for another; no expense arises in this year. The other three are adjustments that change the P&L as well.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-52","question":"The trial balance shows Rent ₹22,000 and, separately, Outstanding Rent ₹2,000 (credit). Among the adjustments it is also noted that rent of ₹2,000 is outstanding. What amount of rent goes to the profit and loss account?","options":["₹22,000","₹24,000","₹20,000","₹26,000"],"answer":0,"explanation":"An item that already appears in the trial balance has been recorded; the note simply describes it. The ₹22,000 already includes the outstanding ₹2,000, so adding it again (₹24,000) double-counts.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-53","question":"Profit before adjustments is ₹3,00,000. Adjustments: closing stock ₹50,000 not yet recorded; salary outstanding ₹8,000; rent prepaid ₹3,000; depreciation 10% on machinery of ₹2,00,000; commission accrued ₹2,500; further bad debts ₹1,500. What is the adjusted profit?","options":["₹3,36,000","₹2,76,000","₹3,46,000","₹3,26,000"],"answer":3,"explanation":"3,00,000 + 50,000 − 8,000 + 3,000 − 20,000 + 2,500 − 1,500 = ₹3,26,000. Reversing outstanding and prepaid gives ₹3,36,000; forgetting depreciation gives ₹3,46,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-54","question":"With the cash book and pass book both showing favourable balances, which item makes the pass-book balance higher than the cash-book balance?","options":["Cheques issued but not yet presented for payment","Cheques deposited but not yet cleared","Bank charges debited only in the pass book","A customer's cheque dishonoured, not yet recorded in the cash book"],"answer":0,"explanation":"The cash book has deducted the cheques issued, but the bank has not paid them yet, so the bank's figure is higher. The other three make the pass book lower.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-55","question":"Assertion (A): An error made by the bank in the pass book needs no entry in the cash book. Reason (R): The cash book is corrected only for items the business itself has not recorded or has recorded wrongly.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A bank error is corrected by the bank; it appears only as a reconciling item in the BRS. The cash book is amended only for the business's own omissions and errors, which is why no entry is needed.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-56","question":"The cash book shows a debit balance of ₹36,000 and the pass book ₹43,250. Cheques issued ₹15,000 are not presented; cheques deposited ₹9,000 are not cleared; bank charges ₹250 and a dividend of ₹3,000 collected by the bank are not in the cash book; a customer's cheque of ₹1,500, deposited and later dishonoured, has not been recorded as dishonoured in the cash book. What is the corrected cash-book balance?","options":["₹43,250","₹38,750","₹40,250","₹37,250"],"answer":3,"explanation":"Correct the cash book only for its own omissions: 36,000 − 250 + 3,000 − 1,500 = ₹37,250. Check: 37,250 − 9,000 + 15,000 = 43,250, the pass-book figure. Treating the dishonour as an addition gives ₹40,250.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-57","question":"A sole trader charges interest on capital at 10% on capital of ₹5,00,000. How many of these statements are true? (1) Net profit falls by ₹50,000. (2) The closing capital is unchanged by the entry. (3) Interest on drawings, if charged, would increase net profit. (4) The entry causes a cash outflow of ₹50,000.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) True: the interest is debited to P&L. (2) True: the same ₹50,000 is credited to capital, offsetting the lower profit. (3) True: interest on drawings is credited to P&L. (4) False: nothing is paid out; it is a book entry. Three are true.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-58","question":"Goods worth ₹5,000 are lost in transit and the carrier accepts a claim of ₹3,000, not yet received. How much is debited to the profit and loss account?","options":["₹5,000","₹3,000","Nil","₹2,000"],"answer":3,"explanation":"The goods are removed from Trading (₹5,000); ₹3,000 is a receivable from the carrier and only the uncovered ₹2,000 is a loss.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-59","question":"Carriage outward (on goods sold) is debited to:","options":["Trading account","Profit and loss account","Balance sheet","Capital account"],"answer":1,"explanation":"Carriage outward is a selling and distribution expense, so it goes to the P&L. Carriage inward is part of the cost of goods and goes to Trading.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-60","question":"Opening stock ₹1,20,000, purchases ₹6,00,000 and sales ₹7,50,000. Goods are sold at cost plus 25%. The owner took goods costing ₹20,000 for personal use, which were not recorded. What should the closing stock be?","options":["₹1,00,000","₹1,20,000","₹1,37,500","₹80,000"],"answer":0,"explanation":"Cost of goods sold = 7,50,000 ÷ 1.25 = 6,00,000. Closing stock = 1,20,000 + 6,00,000 − 20,000 (drawings) − 6,00,000 = ₹1,00,000. Ignoring the goods taken gives ₹1,20,000; using 25% of sales gives ₹1,37,500.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-61","question":"A and B share profits 3 : 2. C is admitted and the new ratio of A, B and C is 5 : 3 : 2. What is the sacrificing ratio of A and B?","options":["3 : 2","1 : 1","5 : 3","2 : 1"],"answer":1,"explanation":"A: 3/5 − 5/10 = 1/10. B: 2/5 − 3/10 = 1/10. Sacrificing ratio 1 : 1, not the old ratio.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-62","question":"A and B share profits 5 : 3. C is admitted for a 1/4 share, which he takes equally from A and B. What is the new ratio of A, B and C?","options":["15 : 9 : 8","5 : 3 : 2","2 : 1 : 1","4 : 3 : 1"],"answer":2,"explanation":"Each gives 1/8. A = 5/8 − 1/8 = 4/8; B = 3/8 − 1/8 = 2/8; C = 2/8 → 2 : 1 : 1. 15 : 9 : 8 is what you get if C takes his share from A and B in their old ratio.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-63","question":"A firm's capital employed is ₹10,00,000 and the normal rate of return is 12%. Its average profit is ₹1,80,000. What is goodwill at three years' purchase of super profit?","options":["₹5,40,000","₹1,80,000","₹5,00,000","₹3,60,000"],"answer":1,"explanation":"Normal profit = 12% × 10,00,000 = 1,20,000. Super profit = 1,80,000 − 1,20,000 = 60,000. Goodwill = 60,000 × 3 = ₹1,80,000. ₹5,40,000 multiplies the whole average profit; ₹5,00,000 capitalises the super profit instead.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-64","question":"A firm earns an average profit of ₹1,50,000; the normal rate of return is 10%. Its assets are ₹18,00,000 and outside liabilities ₹5,00,000. What is goodwill by capitalising the average profit?","options":["₹15,00,000","Nil","₹2,00,000","₹1,50,000"],"answer":2,"explanation":"Capitalised value = 1,50,000 ÷ 10% = 15,00,000. Net assets = 18,00,000 − 5,00,000 = 13,00,000. Goodwill = 15,00,000 − 13,00,000 = ₹2,00,000. Comparing with total assets (ignoring liabilities) would wrongly show no goodwill.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-65","question":"A and B have capitals of ₹3,00,000 and ₹2,00,000 after all adjustments. C is admitted for a 1/4 share and brings ₹2,00,000 as capital, but nothing for goodwill. What is the hidden goodwill of the firm?","options":["₹3,00,000","₹1,00,000","₹25,000","₹75,000"],"answer":1,"explanation":"C's ₹2,00,000 for 1/4 implies total capital of ₹8,00,000. Actual capital including C = 3,00,000 + 2,00,000 + 2,00,000 = ₹7,00,000. Hidden goodwill = ₹1,00,000 (C's share of it ₹25,000). ₹3,00,000 forgets to include C's own capital.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-66","question":"A and B share profits 3 : 2. C is admitted for a 1/5 share and pays ₹50,000 as premium for goodwill. The new ratio is A 2 : B 2 : C 1. How is the premium shared?","options":["A ₹30,000 and B ₹20,000","A ₹50,000 and B nil","A ₹25,000 and B ₹25,000","A ₹40,000 and B ₹10,000"],"answer":1,"explanation":"Premium goes to the partners who sacrifice, in the sacrificing ratio. A: 3/5 − 2/5 = 1/5; B: 2/5 − 2/5 = 0. Only A sacrifices, so A gets all ₹50,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-67","question":"On admitting a partner, the firm revalues: building (book value ₹5,00,000) up by 10%; stock down by ₹15,000; a 5% provision is created on debtors of ₹1,00,000; an unrecorded liability of ₹8,000 is brought in; creditors of ₹2,000 are found not payable. What is the profit on revaluation?","options":["₹20,000","₹40,000","₹24,000","₹29,000"],"answer":2,"explanation":"+50,000 (building) − 15,000 (stock) − 5,000 (provision) − 8,000 (new liability) + 2,000 (creditors written back) = ₹24,000, shared by the old partners in the old ratio. Treating the creditor write-back as a loss gives ₹20,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-68","question":"The partnership deed is silent on all financial matters. Under the Indian Partnership Act, 1932, which of these is allowed?","options":["Interest on capital at 6% a year","Interest at 6% a year on a loan given by a partner to the firm","A salary to the working partner","Sharing profits in the ratio of capitals"],"answer":1,"explanation":"Without agreement, profits are shared equally, there is no interest on capital and no salary, but a partner's loan to the firm carries interest at 6% a year.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-69","question":"Profit for the year is ₹1,20,000. A's capital is ₹4,00,000 and B's ₹2,00,000. Interest on capital is 10%, B gets a salary of ₹2,000 a month, and the remaining profit is shared 3 : 2. What is B's total share?","options":["₹62,000","₹58,400","₹45,200","₹61,600"],"answer":1,"explanation":"Interest: A 40,000, B 20,000. B's salary 24,000. Divisible = 1,20,000 − 60,000 − 24,000 = 36,000; B's 2/5 = 14,400. B total = 20,000 + 24,000 + 14,400 = ₹58,400. ₹61,600 is A's total; ₹62,000 splits the balance equally.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-70","question":"A, B and C share profits 2 : 2 : 1. C is guaranteed a minimum profit of ₹30,000, any shortfall to be borne by A and B in the ratio 3 : 2. The firm's profit is ₹1,00,000. What is A's final share?","options":["₹40,000","₹35,000","₹34,000","₹30,000"],"answer":2,"explanation":"C's normal share = 20,000; shortfall 10,000. A bears 3/5 = 6,000, so A gets 40,000 − 6,000 = ₹34,000 (B gets 36,000). ₹35,000 shares the shortfall equally.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-71","question":"A partner withdraws ₹5,000 at the beginning of every month for 12 months. Interest on drawings is 12% a year. What is the interest on drawings?","options":["₹3,600","₹3,900","₹3,300","₹7,200"],"answer":1,"explanation":"Total ₹60,000; drawings at the start of each month are outstanding for 6.5 months on average: 60,000 × 12% × 6.5/12 = ₹3,900. End-of-month drawings would give 5.5 months (₹3,300) and mid-month 6 months (₹3,600).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-72","question":"A partner withdraws ₹15,000 at the beginning of each quarter. Interest on drawings is 10% a year. What is the interest on drawings for the year?","options":["₹2,250","₹3,000","₹3,750","₹6,000"],"answer":2,"explanation":"Total ₹60,000. Average period for start-of-quarter drawings = (12 + 9 + 6 + 3) ÷ 4 = 7.5 months: 60,000 × 10% × 7.5/12 = ₹3,750. End-of-quarter drawings would give 4.5 months (₹2,250).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-73","question":"A, B and C share profits 4 : 3 : 2. B retires, and A and C take over his share in the ratio 1 : 2. What is the new ratio of A and C?","options":["2 : 1","5 : 4","1 : 2","4 : 3"],"answer":1,"explanation":"B's 3/9 is split 1 : 2: A gains 1/9 and C 2/9. A = 4/9 + 1/9 = 5/9; C = 2/9 + 2/9 = 4/9 → 5 : 4. 1 : 2 is only the gaining ratio.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-74","question":"A, B and C share profits 3 : 2 : 1. C retires; A and B continue in the ratio 3 : 2. Goodwill is valued at ₹1,80,000 and is not to appear in the books. How much does A's capital account contribute to C's share of goodwill?","options":["₹15,000","₹30,000","₹18,000","₹90,000"],"answer":2,"explanation":"C's share = 1,80,000 × 1/6 = 30,000. Gains: A 3/5 − 3/6 = 3/30, B 2/5 − 2/6 = 2/30, so gaining ratio 3 : 2. A pays 30,000 × 3/5 = ₹18,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-75","question":"A and B share profits equally and decide to share 3 : 2 in future. Goodwill is valued at ₹60,000 and is not to be shown in the books. What entry is passed?","options":["B's capital Dr ₹6,000 To A's capital ₹6,000","A's capital Dr ₹6,000 To B's capital ₹6,000","A's capital Dr ₹36,000 To B's capital ₹36,000","No entry is needed for a change in ratio"],"answer":1,"explanation":"A gains 3/5 − 1/2 = 1/10 and B sacrifices 1/10. The gainer compensates the sacrificer: 60,000 × 1/10 = ₹6,000, debited to A and credited to B.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-76","question":"A, B and C share profits 2 : 2 : 1. C dies on 30 June. His share of profit up to death is based on the average of the last three years' profits: ₹1,80,000, ₹2,10,000 and ₹2,70,000. The year starts on 1 April. What is C's share of profit?","options":["₹13,500","₹11,000","₹44,000","₹22,000"],"answer":1,"explanation":"Average profit = 6,60,000 ÷ 3 = 2,20,000. April to June = 3 months: 2,20,000 × 3/12 × 1/5 = ₹11,000. Using only last year's ₹2,70,000 gives ₹13,500; using six months gives ₹22,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-77","question":"Under the fixed capital method, where are the partners' interest on capital, salary and share of profit credited?","options":["To their capital accounts","To the profit and loss account","To their current accounts","To the revaluation account"],"answer":2,"explanation":"With fixed capitals, the capital accounts carry only the agreed capital (and permanent additions or withdrawals); all routine items such as interest, salary, drawings and profit share go through current accounts.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-78","question":"On dissolution, assets (other than cash) with a book value of ₹5,00,000 realise ₹4,40,000. Creditors of ₹1,20,000 accept ₹1,15,000 in full settlement, and realisation expenses of ₹6,000 are paid by the firm. What is the loss on realisation?","options":["₹66,000","₹55,000","₹61,000","₹60,000"],"answer":2,"explanation":"Loss on assets 60,000 − gain on creditors 5,000 + expenses 6,000 = ₹61,000. Treating the creditors' discount as a loss gives ₹66,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-79","question":"After all adjustments, A's capital is ₹4,50,000 and B's ₹3,00,000. C is admitted for a 1/4 share and must bring capital equal to 1/4 of the total capital of the new firm. How much does C bring?","options":["₹1,87,500","₹2,50,000","₹3,00,000","₹2,00,000"],"answer":1,"explanation":"Old partners' ₹7,50,000 is 3/4 of the new total, so total = 10,00,000 and C brings ₹2,50,000. ₹1,87,500 is 1/4 of the old capital, not of the new total.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-80","question":"A and B share profits 3 : 2 and have capitals of ₹3,00,000 and ₹2,20,000. C is admitted for 1/5 and brings ₹1,20,000. A and B keep their ratio between themselves and agree to adjust their capitals on the basis of C's capital, in the new profit-sharing ratio. What adjustment does A make?","options":["A brings in ₹12,000","A withdraws ₹12,000","A withdraws ₹1,20,000","A brings in ₹48,000"],"answer":1,"explanation":"Total capital implied by C = 1,20,000 × 5 = 6,00,000. New ratio: A 3/5 × 4/5 = 12/25, B 8/25, C 5/25. A's capital should be 6,00,000 × 12/25 = 2,88,000, so A withdraws 3,00,000 − 2,88,000 = ₹12,000 (B, whose capital should be ₹1,92,000, withdraws ₹28,000).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-81","question":"The partnership deed allows interest on capital: A ₹24,000 and B ₹16,000. The firm's profit is only ₹30,000. Interest on capital is treated as an appropriation of profit. How is the profit distributed?","options":["A ₹24,000 and B ₹16,000, and the ₹10,000 shortfall is shared as a loss","A ₹15,000 and B ₹15,000","A ₹18,000 and B ₹12,000","A ₹24,000 and B ₹6,000"],"answer":2,"explanation":"As an appropriation, interest on capital cannot exceed the available profit; the ₹30,000 is shared in the ratio of the interest, 24 : 16 = 3 : 2, giving A ₹18,000 and B ₹12,000. (If interest were a charge, it would be allowed in full and create a loss.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-82","question":"When the partnership deed is silent, which of these rules apply under the Indian Partnership Act, 1932? (1) Profits and losses are shared equally (2) No interest on capital (3) Interest at 6% a year on partners' loans (4) No salary or commission to any partner","options":["(1) and (2) only","(1), (2) and (3) only","(1), (2), (3) and (4)","(2) and (4) only"],"answer":2,"explanation":"All four are the default rules of Section 13 when the partners have not agreed otherwise.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-83","question":"Goodwill is to be valued at two years' purchase of the weighted average profit of the last three years, weighted 1, 2 and 3 (latest year highest). Profits were ₹1,00,000, ₹1,20,000 and ₹1,50,000; the latest year's profit includes a non-recurring gain of ₹30,000. What is goodwill?","options":["₹2,63,333","₹2,33,333","₹2,26,667","₹1,16,667"],"answer":1,"explanation":"Normalised latest profit = 1,20,000. Weighted average = (1,00,000 × 1 + 1,20,000 × 2 + 1,20,000 × 3) ÷ 6 = 7,00,000 ÷ 6 = 1,16,667. Goodwill = 2 × 1,16,667 = ₹2,33,333. Keeping the non-recurring gain gives ₹2,63,333.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-84","question":"On admitting a partner, the partners want the assets and liabilities to stay at their old book values even though some have been revalued. What do they use?","options":["A revaluation account, closed to the new ratio","A realisation account","A memorandum revaluation account","A goodwill account"],"answer":2,"explanation":"A memorandum revaluation account records the net gain or loss, credited to the old partners in the old ratio, and then reverses it among all partners in the new ratio, so the book values stay unchanged.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-85","question":"Goodwill of ₹40,000 already stands in the books when a new partner is admitted. What happens to it?","options":["It is carried forward unchanged","It is written off among the old partners in the old ratio","It is written off among all partners in the new ratio","It is credited to the new partner"],"answer":1,"explanation":"Existing goodwill belongs to the old partners and is written off to their capital accounts in the old ratio before the new partner's goodwill is dealt with.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-86","question":"A, B and C share profits 2 : 2 : 1. C retires. The balance sheet shows a general reserve of ₹60,000 and a debit balance of ₹15,000 in the profit and loss account. What net amount is credited to C's capital for these two items?","options":["₹12,000","₹9,000","₹15,000","₹3,000"],"answer":1,"explanation":"Both items are distributed in the old ratio: (60,000 − 15,000) × 1/5 = ₹9,000. ₹12,000 forgets the accumulated loss.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-87","question":"A partner's closing capital is ₹2,30,000 under the fluctuating capital method. During the year his drawings were ₹30,000 and his share of profit ₹40,000. Interest on capital at 10% a year on opening capital has been credited to his capital account. What was the interest on capital?","options":["₹23,000","₹20,000","₹22,000","₹26,000"],"answer":1,"explanation":"Closing = opening × 1.10 + 40,000 − 30,000, so 1.1 × opening = 2,20,000 and opening = 2,00,000. Interest = ₹20,000. ₹22,000 forgets that the interest itself sits inside the closing balance.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-88","question":"The document setting out the terms agreed among partners is called the:","options":["Memorandum of association","Prospectus","Partnership deed (articles of partnership)","Certificate of incorporation"],"answer":2,"explanation":"A partnership deed, also called articles of partnership, records capital, profit ratio, interest, salaries and other terms. The others relate to companies.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-89","question":"A new partner pays the old partners their share of goodwill privately, outside the firm. What entry is made in the firm's books?","options":["Cash Dr To Premium for Goodwill","No entry","Goodwill A/c Dr To Old partners' capitals","New partner's capital Dr To Old partners' capitals"],"answer":1,"explanation":"The payment does not pass through the firm, so the firm's books record nothing for it.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-90","question":"A, B and C share profits 5 : 3 : 2. D is admitted for 1/5, taking 1/10 from A and the rest equally from B and C. What is the new ratio of A, B, C and D?","options":["9 : 5 : 2 : 4","8 : 6 : 2 : 4","8 : 5 : 3 : 4","20 : 12 : 8 : 10"],"answer":2,"explanation":"A gives 1/10; B and C give 1/20 each. A = 5/10 − 1/10 = 8/20; B = 6/20 − 1/20 = 5/20; C = 4/20 − 1/20 = 3/20; D = 4/20 → 8 : 5 : 3 : 4. 20 : 12 : 8 : 10 assumes everyone gives in the old ratio.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-91","question":"Under Schedule III, where is the securities premium shown in a company's balance sheet?","options":["Under 'Other equity' (reserves and surplus)","Under 'Share capital'","Under 'Other current liabilities'","As income in the statement of profit and loss"],"answer":0,"explanation":"Securities premium is part of reserves, shown under Other equity; it is never income and is not share capital.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-92","question":"1,000 equity shares of ₹10 each were issued at par and ₹8 per share has been called up. A shareholder holding all 1,000 shares paid ₹5 per share and failed to pay the ₹3 call, so the shares are forfeited. What is credited to the Share Forfeiture account?","options":["₹5,000","₹8,000","₹3,000","₹10,000"],"answer":0,"explanation":"Share capital is debited with the called-up amount (₹8,000), Calls in arrears credited with the unpaid ₹3,000, and Share Forfeiture credited with the amount actually received, ₹5,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-93","question":"500 shares of ₹10 were issued at ₹12; the ₹2 premium was payable with allotment. Application ₹3, allotment ₹5 (including premium), first call ₹2. A holder of 500 shares paid only the application money and the shares were forfeited after the first call. What is the forfeiture entry?","options":["Share capital Dr ₹4,000; Securities premium Dr ₹1,000; To Share forfeiture ₹1,500 and the unpaid allotment and call accounts","Share capital Dr ₹4,000; To Share forfeiture ₹1,500 and the unpaid allotment and call accounts, with premium left untouched","Share capital Dr ₹5,000; To Share forfeiture ₹1,500 and the unpaid accounts","Share capital Dr ₹4,000; Securities premium Dr ₹1,000; To Share forfeiture ₹2,500 and the unpaid accounts"],"answer":0,"explanation":"Called-up capital = 3 + 3 + 2 = ₹8 × 500 = ₹4,000. The premium was never received, so it is reversed (Dr ₹1,000). Forfeiture = amount received = 500 × 3 = ₹1,500. Credits: unpaid allotment ₹2,500 + unpaid call ₹1,000 + forfeiture ₹1,500 = ₹5,000 = debits.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-94","question":"200 fully called shares of ₹10 each, on which ₹6 per share had been received, were forfeited. 150 of them are reissued as fully paid at ₹8 per share. What amount is transferred to capital reserve?","options":["₹900","₹300","₹1,200","₹600"],"answer":3,"explanation":"Forfeited amount on the 150 reissued shares = 150 × 6 = 900. Discount on reissue = 150 × 2 = 300. Transfer = 900 − 300 = ₹600. The forfeiture on the other 50 shares (₹300) stays in the forfeiture account until they are reissued.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-95","question":"300 shares of ₹10 each, ₹7 called up, were forfeited for non-payment of a ₹3 call (the holder had paid ₹4). They are reissued as ₹10 fully paid. What is the maximum discount per share allowed on reissue?","options":["₹3","₹6","₹7","₹4"],"answer":3,"explanation":"Discount on reissue cannot exceed the amount forfeited on those shares, which is the ₹4 per share received from the original holder.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-96","question":"A company received applications for 30,000 shares and allotted 20,000 pro rata. Application money is ₹3 and allotment money ₹4 per share; excess application money is adjusted against allotment. How much does an applicant for 600 shares pay on allotment?","options":["₹1,000","₹1,600","₹2,400","₹600"],"answer":0,"explanation":"He gets 600 × 20,000/30,000 = 400 shares. Paid on application 600 × 3 = 1,800; needed 400 × 3 = 1,200; excess 600. Allotment due 400 × 4 = 1,600, less 600 = ₹1,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-97","question":"Shares of ₹10 are payable ₹3 on application, ₹4 on allotment and ₹3 on call; allotment is pro rata at 2 shares for every 3 applied, with excess application money adjusted against allotment. An applicant for 600 shares fails to pay allotment and call, and his shares are forfeited. What is credited to Share Forfeiture?","options":["₹1,200","₹600","₹4,000","₹1,800"],"answer":3,"explanation":"He was allotted 400 shares and paid 600 × 3 = ₹1,800 on application. ₹1,200 was applied to application money and ₹600 to allotment, so the whole ₹1,800 has been received on his 400 shares and is forfeited.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-98","question":"1,000 debentures of ₹100 are issued at ₹95 and are redeemable at ₹105. What is the loss on issue of debentures?","options":["₹10,000","₹5,000","₹15,000","Nil"],"answer":0,"explanation":"Discount ₹5 + premium payable on redemption ₹5 = ₹10 per debenture; × 1,000 = ₹10,000, written off over the life of the debentures.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-99","question":"Under Table F of the Companies Act, 2013 (where the articles adopt it), what interest applies to calls in arrears and calls in advance?","options":["Up to 10% a year on calls in arrears; up to 12% a year on calls in advance","12% on calls in arrears; 10% on calls in advance","10% on both","No interest is allowed on either"],"answer":0,"explanation":"Table F lets directors charge interest on unpaid calls at up to 10% a year, and pay interest on calls received in advance at up to 12% a year, unless the company decides otherwise.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-100","question":"Bonus shares cannot be issued out of which of these?","options":["Free reserves","Securities premium","Capital redemption reserve","Revaluation reserve"],"answer":3,"explanation":"Section 63 permits bonus issues from free reserves, securities premium and capital redemption reserve, but not from reserves created by revaluing assets.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-101","question":"Which sequence of share capital is always correct?","options":["Paid-up ≥ called-up ≥ issued","Subscribed ≥ issued ≥ authorised","Called-up ≥ subscribed ≥ paid-up","Authorised ≥ issued ≥ subscribed ≥ called-up ≥ paid-up"],"answer":3,"explanation":"A company cannot issue more than it is authorised to, cannot have more subscribed than issued, cannot call more than subscribed and cannot receive more than called (calls in advance are shown separately).","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-102","question":"Net profit is ₹2,00,000. Depreciation ₹40,000; profit on sale of machinery ₹10,000; increase in debtors ₹25,000; decrease in stock ₹15,000; increase in creditors ₹12,000; decrease in outstanding expenses ₹3,000. What is the cash from operating activities?","options":["₹2,49,000","₹2,31,000","₹2,09,000","₹2,29,000"],"answer":3,"explanation":"2,00,000 + 40,000 − 10,000 − 25,000 + 15,000 + 12,000 − 3,000 = ₹2,29,000. Reversing every working-capital sign gives ₹2,31,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-103","question":"The provision for tax was ₹60,000 at the start of the year and ₹80,000 at the end; the tax charged to the profit and loss account was ₹95,000. How much tax was paid during the year?","options":["₹75,000","₹95,000","₹1,15,000","₹20,000"],"answer":0,"explanation":"Tax paid = opening provision + charge − closing provision = 60,000 + 95,000 − 80,000 = ₹75,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-104","question":"Machinery (net of depreciation) was ₹5,00,000 at the start and ₹6,20,000 at the end of the year. Depreciation for the year was ₹70,000, and a machine with a book value of ₹40,000 was sold for ₹35,000. How much machinery was bought?","options":["₹1,20,000","₹1,90,000","₹2,25,000","₹2,30,000"],"answer":3,"explanation":"Closing = opening + purchases − depreciation − book value sold: purchases = 6,20,000 + 70,000 + 40,000 − 5,00,000 = ₹2,30,000. Using the sale price instead of book value gives ₹2,25,000; forgetting the sale gives ₹1,90,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-105","question":"In a manufacturing company's cash-flow statement, how is interest received on investments classified?","options":["Investing activity","Operating activity","Financing activity","It is not shown"],"answer":0,"explanation":"For a non-financial enterprise, interest and dividends received are returns on investments and are shown under investing activities; for a bank or finance company they are operating.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-106","question":"Which of these is excluded from the cash-flow statement and disclosed only by way of a note?","options":["Purchase of machinery for cash","Redemption of debentures in cash","Payment of dividend","Conversion of debentures into equity shares"],"answer":3,"explanation":"Converting debentures into shares involves no cash, so it is a non-cash financing transaction disclosed separately; the other three are cash flows.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-107","question":"Which of these qualifies as a cash equivalent?","options":["A treasury bill with an original maturity of three months","Equity shares of a listed company held for trading","A fixed deposit with an original maturity of one year","An investment in a subsidiary"],"answer":0,"explanation":"Cash equivalents are short-term, highly liquid investments with insignificant risk of change in value, normally with a maturity of three months or less from acquisition. Equity shares can change in value significantly.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-108","question":"During the year a company issued equity shares of ₹5,00,000 at a 10% premium, redeemed debentures of ₹2,00,000 at a 5% premium, paid debenture interest of ₹30,000 and dividends of ₹80,000, and raised a long-term loan of ₹1,00,000. What is the net cash from financing activities?","options":["₹3,30,000","₹3,40,000","₹2,80,000","₹4,40,000"],"answer":0,"explanation":"+5,50,000 (issue with premium) − 2,10,000 (redemption with premium) − 30,000 − 80,000 + 1,00,000 = ₹3,30,000. Redeeming at par gives ₹3,40,000; ignoring the issue premium gives ₹2,80,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-109","question":"Profit before tax is ₹3,00,000 after crediting dividend received ₹20,000 and profit on sale of investments ₹15,000, and after charging depreciation ₹50,000, goodwill amortisation ₹10,000 and debenture interest ₹25,000. Inventory rose by ₹30,000, trade payables fell by ₹8,000 and prepaid expenses fell by ₹2,000. Tax paid was ₹70,000. What is the cash from operating activities?","options":["₹2,19,000","₹2,79,000","₹3,16,000","₹2,44,000"],"answer":3,"explanation":"Operating profit before working-capital changes = 3,00,000 − 20,000 − 15,000 + 50,000 + 10,000 + 25,000 = 3,50,000. Working capital: −30,000 − 8,000 + 2,000 → 3,14,000. Less tax 70,000 = ₹2,44,000. Leaving interest in operating gives ₹2,19,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-110","question":"Which of these increases cash from operating activities under the indirect method?","options":["Increase in inventory","Decrease in trade payables","Profit on sale of a fixed asset","Decrease in trade receivables"],"answer":3,"explanation":"Collecting receivables releases cash, so a fall in receivables is added. More inventory or lower payables absorb cash, and a profit on sale is deducted because the cash is shown under investing.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-111","question":"How is dividend paid by a manufacturing company classified in its cash-flow statement under Indian standards?","options":["Operating activity","Financing activity","Investing activity","It is not shown, being an appropriation of profit"],"answer":1,"explanation":"Dividends paid are a cost of obtaining financial resources, so they are financing outflows.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-112","question":"How many of these statements about a manufacturing company's cash-flow statement are true? (1) A bonus issue of shares does not appear in it. (2) Loss on sale of machinery is added back in operating activities. (3) Proceeds from the sale of machinery appear under investing activities. (4) Interest paid is an operating outflow.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) True: no cash moves. (2) True: the loss is non-cash and the proceeds are investing. (3) True. (4) False for a non-financial company: interest paid is financing (it is operating only for financial enterprises). Three are true.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-113","question":"For which purpose can a company NOT use its securities premium?","options":["Paying a cash dividend","Issuing fully paid bonus shares","Writing off preliminary expenses","Buying back its own shares"],"answer":0,"explanation":"Section 52 lists the permitted uses: fully paid bonus shares, writing off preliminary expenses, issue expenses or discount, premium on redemption, and buy-back. It cannot be distributed as dividend.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-114","question":"A company buys a building for ₹6,00,000 and pays the vendor by issuing equity shares of ₹10 each at a 20% premium. How many shares are issued?","options":["50,000","60,000","72,000","48,000"],"answer":0,"explanation":"Issue price = 10 + 2 = ₹12. Shares = 6,00,000 ÷ 12 = 50,000. 60,000 divides by face value and ignores the premium.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-115","question":"A company issues its own debentures of ₹5,00,000 to a bank as collateral security for a loan of ₹4,00,000. What is the correct treatment?","options":["Record a liability of ₹9,00,000 (loan plus debentures)","Credit debentures ₹5,00,000 and debit cash ₹5,00,000","Treat the debentures as income until the loan is repaid","No new liability: either just a note under the loan, or a debentures account offset by a debenture suspense account"],"answer":3,"explanation":"Collateral debentures become a liability only if the company defaults on the loan. They are shown by a note, or recorded and immediately offset by a debenture suspense account, so the only real liability is the ₹4,00,000 loan.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-116","question":"Preference shares carry a preferential right as to:","options":["Voting on all resolutions","Appointment of directors","Bonus shares","Dividend and return of capital on winding up"],"answer":3,"explanation":"Preference shareholders get a fixed dividend before equity shareholders and are repaid capital before them on winding up; their voting rights are limited.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-117","question":"A shareholder holding 100 shares of ₹10 (fully called) paid only ₹2 on application and ₹3 on allotment; his shares were forfeited. 60 of them are reissued as fully paid at ₹9 each. What is transferred to capital reserve?","options":["₹300","₹200","₹60","₹240"],"answer":3,"explanation":"Forfeited per share = ₹5; on 60 shares = 300. Discount on reissue = 60 × 1 = 60. Capital reserve = 300 − 60 = ₹240. The ₹200 on the 40 unissued shares stays in the forfeiture account.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-118","question":"How is interest received on loans given classified in the cash-flow statement of a finance company?","options":["Investing activity","Financing activity","It is not shown","Operating activity"],"answer":3,"explanation":"Lending is the main revenue-producing activity of a finance company, so interest received is an operating cash flow.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-119","question":"How is a bank overdraft that is repayable on demand and forms an integral part of a company's cash management treated under Ind AS 7?","options":["As a component of cash and cash equivalents","As a financing inflow when drawn","As an investing activity","As an operating outflow"],"answer":0,"explanation":"Ind AS 7 includes such overdrafts as a (negative) component of cash and cash equivalents, since the balance often swings between positive and overdrawn.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-120","question":"A company's cash from operations (after tax) is ₹4,20,000. It spent ₹2,50,000 on new plant and received ₹30,000 from selling old plant. Taking free cash flow as operating cash flow less net capital expenditure, what is the free cash flow?","options":["₹1,70,000","₹2,00,000","₹4,50,000","₹2,30,000"],"answer":1,"explanation":"Net capex = 2,50,000 − 30,000 = 2,20,000. FCF = 4,20,000 − 2,20,000 = ₹2,00,000. Ignoring the disposal proceeds gives ₹1,70,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-121","question":"Current assets are ₹4,80,000 and current liabilities ₹2,00,000. What is the current ratio?","options":["0.42 : 1","1.4 : 1","2.4 : 1","2.8 : 1"],"answer":2,"explanation":"Current ratio = 4,80,000 ÷ 2,00,000 = 2.4 : 1.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-122","question":"Current assets of ₹6,00,000 include inventory of ₹1,80,000 and prepaid expenses of ₹20,000. Current liabilities are ₹2,50,000. What is the quick ratio?","options":["1.68 : 1","2.4 : 1","1.6 : 1","1.52 : 1"],"answer":2,"explanation":"Quick assets = 6,00,000 − 1,80,000 − 20,000 = 4,00,000; quick ratio = 4,00,000 ÷ 2,50,000 = 1.6 : 1. Removing only inventory gives 1.68.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-123","question":"A company's current ratio is 2.5 : 1, its quick ratio 1.5 : 1 and its working capital ₹1,20,000. Current assets consist only of quick assets and inventory. What is the inventory?","options":["₹1,20,000","₹40,000","₹80,000","₹2,00,000"],"answer":2,"explanation":"CA − CL = 1,20,000 and CA = 2.5 CL, so 1.5 CL = 1,20,000: CL = 80,000, CA = 2,00,000. Quick assets = 1.5 × 80,000 = 1,20,000, so inventory = 2,00,000 − 1,20,000 = ₹80,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-124","question":"A company's current ratio is 2 : 1. Which of these would increase it? (1) Paying a trade creditor in cash (2) Buying stock on credit (3) Raising a long-term loan in cash (4) Selling stock costing ₹10,000 for ₹8,000 cash","options":["(1) only","(1) and (3) only","(1), (3) and (4)","(2) and (3) only"],"answer":1,"explanation":"(1) Equal fall in CA and CL raises a ratio above 1 (e.g. 4/2 → 3/1). (2) Equal rise lowers it (4/2 → 5/3). (3) CA rises with no current liability: up. (4) CA falls by the ₹2,000 loss: down. So (1) and (3).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-125","question":"Equity share capital ₹5,00,000; reserves ₹3,00,000; 10% debentures ₹4,00,000; long-term bank loan ₹2,00,000; trade creditors ₹1,00,000. What is the debt–equity ratio?","options":["0.875 : 1","1.2 : 1","0.75 : 1","1.33 : 1"],"answer":2,"explanation":"Long-term debt = 4,00,000 + 2,00,000 = 6,00,000; equity = 5,00,000 + 3,00,000 = 8,00,000. Ratio = 0.75 : 1. Including creditors gives 0.875; leaving out reserves gives 1.2.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-126","question":"Profit after tax is ₹2,10,000, the tax rate is 30% and debenture interest is ₹60,000. What is the interest coverage ratio?","options":["3.5 times","5 times","6 times","4.5 times"],"answer":2,"explanation":"PBT = 2,10,000 ÷ 0.7 = 3,00,000; EBIT = 3,00,000 + 60,000 = 3,60,000. Coverage = 3,60,000 ÷ 60,000 = 6 times. Using PAT gives 3.5 and PBT gives 5.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-127","question":"Cost of goods sold is ₹7,20,000; opening inventory ₹80,000 and closing inventory ₹1,00,000. What is the inventory turnover ratio?","options":["7.2 times","9 times","8 times","10 times"],"answer":2,"explanation":"Average inventory = (80,000 + 1,00,000) ÷ 2 = 90,000. Turnover = 7,20,000 ÷ 90,000 = 8 times.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-128","question":"Sales are ₹12,00,000 with a gross profit of 25% on sales. Opening inventory is ₹1,40,000 and closing inventory ₹1,60,000. What is the inventory turnover ratio?","options":["8 times","6.4 times","7.5 times","6 times"],"answer":3,"explanation":"COGS = 75% × 12,00,000 = 9,00,000; average inventory = 1,50,000; turnover = 6 times. Using sales gives 8; treating 25% as a mark-up on cost gives 6.4.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-129","question":"Total sales are ₹9,60,000, of which 75% are on credit. Debtors were ₹80,000 at the start and ₹1,00,000 at the end of the year, and bills receivable of ₹20,000 are held at the end. Using a 360-day year, what is the average collection period?","options":["45 days","37.5 days","50 days","60 days"],"answer":2,"explanation":"Credit sales = 7,20,000. Closing receivables = 1,00,000 + 20,000 = 1,20,000; average = (80,000 + 1,20,000) ÷ 2 = 1,00,000. Turnover = 7.2; period = 360 ÷ 7.2 = 50 days. Ignoring bills receivable gives 45 days; using total sales gives 37.5.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-130","question":"Goods are sold at a mark-up of 25% on cost. What is the gross profit ratio?","options":["25%","20%","33.33%","12.5%"],"answer":1,"explanation":"Cost 100, price 125, profit 25: margin on sales = 25 ÷ 125 = 20%.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-131","question":"Net profit margin is 8%, total asset turnover 1.5 times, total assets ₹12,00,000 and shareholders' equity ₹4,80,000. What is the return on equity?","options":["12%","30%","20%","25%"],"answer":1,"explanation":"DuPont: ROE = margin × asset turnover × equity multiplier = 8% × 1.5 × (12,00,000 ÷ 4,80,000 = 2.5) = 30%. 12% is the return on assets.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-132","question":"A company's ROE is 18%, its ROA 6% and its net profit margin 4%. Assets are financed only by equity and liabilities. What is its total liabilities to total assets ratio?","options":["33.33%","50%","66.67%","75%"],"answer":2,"explanation":"Equity multiplier = ROE ÷ ROA = 3, so equity is one-third of assets and liabilities two-thirds: 66.67%. (Asset turnover = 6% ÷ 4% = 1.5 is not needed.)","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-133","question":"Shareholders' funds are ₹6,00,000 and total assets ₹10,00,000. What is the proprietary ratio?","options":["0.6 : 1","1.5 : 1","0.4 : 1","1.67 : 1"],"answer":0,"explanation":"Proprietary ratio = shareholders' funds ÷ total assets = 0.6 : 1.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-134","question":"Current ratio 2.5 : 1; quick ratio 1.5 : 1; current liabilities ₹1,60,000; inventory turnover (on cost of goods sold) 6 times, with opening and closing inventory equal; gross profit 20% of sales. What are the sales?","options":["₹9,60,000","₹11,52,000","₹12,00,000","₹19,20,000"],"answer":2,"explanation":"Inventory = (2.5 − 1.5) × 1,60,000 = 1,60,000. COGS = 6 × 1,60,000 = 9,60,000. Sales = 9,60,000 ÷ 0.8 = ₹12,00,000. Adding 20% to cost gives ₹11,52,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-135","question":"EBIT is ₹3,00,000, including ₹20,000 income from non-trade investments of ₹2,00,000. Capital employed is equity ₹12,00,000 plus long-term debt ₹8,00,000 (these funds include the investments). What is the ROCE after excluding the investments and their income?","options":["15%","15.56%","25%","14%"],"answer":1,"explanation":"Operating EBIT = 3,00,000 − 20,000 = 2,80,000; operating capital employed = 20,00,000 − 2,00,000 = 18,00,000. ROCE = 15.56%. Not excluding either gives 15%.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-136","question":"Profit after tax is ₹12,00,000, preference dividend ₹2,00,000, and there are 2,00,000 equity shares. What is the EPS?","options":["₹6","₹5","₹7","₹4"],"answer":1,"explanation":"EPS = (12,00,000 − 2,00,000) ÷ 2,00,000 = ₹5. Forgetting the preference dividend gives ₹6.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-137","question":"EPS is ₹5, the market price ₹60 and the dividend per share ₹2. What are the payout ratio and the dividend yield?","options":["Payout 60%, yield 3.33%","Payout 40%, yield 8.33%","Payout 40%, yield 3.33%","Payout 2.5%, yield 12%"],"answer":2,"explanation":"Payout = DPS ÷ EPS = 2 ÷ 5 = 40%. Yield = DPS ÷ price = 2 ÷ 60 = 3.33%. (8.33% is EPS ÷ price, the earnings yield.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-138","question":"Quick assets are ₹3,60,000 and current liabilities ₹3,00,000. The company then buys inventory worth ₹60,000 on credit. What is the new quick ratio?","options":["1.2 : 1","1.4 : 1","1.0 : 1","0.83 : 1"],"answer":2,"explanation":"Inventory is not a quick asset, but the creditor is a current liability: 3,60,000 ÷ 3,60,000 = 1.0 : 1.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-139","question":"Liquidity ratios measure a firm's:","options":["Long-term solvency","Profitability","Efficiency in using its assets","Ability to meet short-term obligations"],"answer":3,"explanation":"Current and quick ratios test whether current assets can cover current liabilities.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-140","question":"Cost of goods sold is ₹6,00,000, operating expenses ₹1,00,000 and net sales ₹8,75,000. What is the operating ratio?","options":["68.57%","80%","20%","85%"],"answer":1,"explanation":"Operating ratio = (COGS + operating expenses) ÷ net sales = 7,00,000 ÷ 8,75,000 = 80%. 68.57% leaves out operating expenses.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-141","question":"Profit after tax ₹3,00,000; depreciation ₹50,000; interest on term loan ₹1,00,000; principal instalment due ₹1,50,000. What is the debt service coverage ratio?","options":["1.4 times","3.0 times","1.8 times","4.5 times"],"answer":2,"explanation":"DSCR = (PAT + depreciation + interest) ÷ (interest + principal) = 4,50,000 ÷ 2,50,000 = 1.8 times. Leaving interest out of the numerator gives 1.4.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-142","question":"Current assets are ₹3,00,000 and current liabilities ₹1,50,000. A machine is bought for ₹50,000: ₹20,000 in cash and the rest by a three-month bill payable. What is the new current ratio?","options":["1.87 : 1","1.67 : 1","1.56 : 1","2.0 : 1"],"answer":2,"explanation":"CA = 3,00,000 − 20,000 = 2,80,000; CL = 1,50,000 + 30,000 = 1,80,000. Ratio = 1.56 : 1. Forgetting the bill payable gives 1.87.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-143","question":"Sales are ₹18,00,000, fixed assets ₹6,00,000 and current assets ₹3,00,000. What is the total asset turnover?","options":["3 times","2 times","6 times","1.5 times"],"answer":1,"explanation":"Total assets = 9,00,000; turnover = 18,00,000 ÷ 9,00,000 = 2 times. 3 times is the fixed-asset turnover.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-144","question":"Assertion (A): A very high current ratio may indicate poor working-capital management. Reason (R): Excess current assets such as idle cash or slow-moving stock earn little or no return.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A high ratio is safe for creditors but often means funds are locked in idle cash, excess stock or slow debtors, which earn nothing. That is exactly why it can signal inefficiency.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-145","question":"How many of these statements are true? (1) Issuing equity shares for cash lowers the debt–equity ratio. (2) Converting debentures into equity shares lowers the debt–equity ratio. (3) Redeeming debentures out of cash raises the current ratio. (4) A bonus issue changes the debt–equity ratio.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) True: equity rises. (2) True: debt falls and equity rises. (3) False: cash (a current asset) falls with no change in current liabilities, so the ratio falls. (4) False: reserves become share capital, total equity is unchanged. Two are true.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-146","question":"Credit sales are ₹7,20,000 and the average collection period is 45 days (360-day year). What are the average debtors?","options":["₹1,60,000","₹72,000","₹90,000","₹80,000"],"answer":2,"explanation":"Debtors turnover = 360 ÷ 45 = 8; average debtors = 7,20,000 ÷ 8 = ₹90,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-147","question":"Which of these is a solvency (long-term) ratio?","options":["Current ratio","Inventory turnover","Debt–equity ratio","Gross profit ratio"],"answer":2,"explanation":"Debt–equity measures long-term financial risk; current ratio is liquidity, inventory turnover is activity and GP ratio is profitability.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-148","question":"Fixed-asset turnover is 4 times on fixed assets of ₹3,00,000; gross profit is 25% of sales; inventory turnover is 8 times on cost of goods sold. What is the average inventory?","options":["₹1,50,000","₹1,20,000","₹1,12,500","₹1,00,000"],"answer":2,"explanation":"Sales = 4 × 3,00,000 = 12,00,000; COGS = 9,00,000; average inventory = 9,00,000 ÷ 8 = ₹1,12,500. Dividing sales by 8 gives ₹1,50,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-149","question":"Net profit is ₹72,000, gross sales ₹9,60,000 and sales returns ₹60,000. What is the net profit ratio?","options":["7.5%","12%","8%","9%"],"answer":2,"explanation":"Net sales = 9,00,000; NP ratio = 72,000 ÷ 9,00,000 = 8%. Using gross sales gives 7.5%.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-150","question":"Which statement about financial leverage and the gap between ROE and ROA is correct?","options":["ROE always exceeds ROA once a firm borrows","Leverage raises ROE whenever interest rates are positive","ROE equals ROA multiplied by the debt ratio","Borrowing raises ROE only while the return earned on assets exceeds the after-tax cost of debt"],"answer":3,"explanation":"Debt magnifies returns both ways. If assets earn more than debt costs after tax, the surplus accrues to equity and ROE rises; if they earn less, ROE falls below what it would be unlevered.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-151","question":"Sales are ₹5,00,000, variable costs ₹3,00,000 and fixed costs ₹1,20,000. What is the P/V ratio?","options":["40%","60%","16%","24%"],"answer":0,"explanation":"Contribution = 5,00,000 − 3,00,000 = 2,00,000; P/V ratio = 2,00,000 ÷ 5,00,000 = 40%. 60% is the variable-cost ratio.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-152","question":"Fixed costs are ₹1,20,000 and the P/V ratio is 40%. What is the break-even sales?","options":["₹2,00,000","₹4,80,000","₹1,68,000","₹3,00,000"],"answer":3,"explanation":"BEP = fixed cost ÷ P/V ratio = 1,20,000 ÷ 0.40 = ₹3,00,000. Dividing by the variable-cost ratio (60%) gives ₹2,00,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-153","question":"Actual sales are ₹5,00,000, break-even sales ₹3,00,000 and the P/V ratio 40%. What is the profit?","options":["₹80,000","₹1,20,000","₹2,00,000","₹60,000"],"answer":0,"explanation":"Margin of safety = 2,00,000; profit = MoS × P/V ratio = 2,00,000 × 40% = ₹80,000. ₹2,00,000 is the margin of safety itself.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-154","question":"With sales of ₹4,00,000 a firm earns ₹20,000; with sales of ₹5,00,000 it earns ₹50,000. Selling price and costs per unit do not change. What is the break-even sales?","options":["₹3,33,333","₹3,00,000","₹2,50,000","₹4,00,000"],"answer":0,"explanation":"P/V ratio = change in profit ÷ change in sales = 30,000 ÷ 1,00,000 = 30%. Fixed cost = 4,00,000 × 30% − 20,000 = 1,00,000. BEP = 1,00,000 ÷ 0.30 = ₹3,33,333.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-155","question":"Selling price ₹50 a unit, variable cost ₹30 a unit, fixed costs ₹2,00,000. The firm wants a profit after tax of ₹60,000; the tax rate is 25%. How many units must it sell?","options":["13,000 units","13,750 units","10,000 units","14,000 units"],"answer":3,"explanation":"Profit before tax needed = 60,000 ÷ 0.75 = 80,000. Units = (2,00,000 + 80,000) ÷ 20 = 14,000. Ignoring tax gives 13,000; adding 25% to the after-tax profit (75,000) gives 13,750.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-156","question":"Product A sells at ₹100 with variable cost ₹60; product B sells at ₹80 with variable cost ₹60. They are sold in the ratio 3 units of A to 2 units of B, and fixed costs are ₹1,60,000. How many units in total must be sold to break even?","options":["4,000 units","5,000 units","5,333 units","8,000 units"],"answer":1,"explanation":"Contribution per mix of 5 units = 3 × 40 + 2 × 20 = 160, so ₹32 per unit on average. BEP = 1,60,000 ÷ 32 = 5,000 units (3,000 A and 2,000 B). A simple average contribution of ₹30 gives 5,333.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-157","question":"Direct materials ₹2,00,000; direct labour ₹1,20,000; direct expenses ₹30,000; factory overheads ₹80,000; opening work-in-progress ₹20,000; closing work-in-progress ₹30,000. What is the works (factory) cost?","options":["₹4,20,000","₹4,30,000","₹4,70,000","₹3,50,000"],"answer":0,"explanation":"Prime cost = 3,50,000. Works cost = 3,50,000 + 80,000 + 20,000 − 30,000 = ₹4,20,000. ₹4,30,000 forgets the work-in-progress adjustment; ₹3,50,000 is prime cost.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-158","question":"Cost of production is ₹5,00,000; opening finished goods ₹40,000; closing finished goods ₹60,000; selling and distribution overheads ₹30,000. What is the cost of sales?","options":["₹4,80,000","₹5,10,000","₹5,30,000","₹5,00,000"],"answer":1,"explanation":"Cost of goods sold = 5,00,000 + 40,000 − 60,000 = 4,80,000; cost of sales = 4,80,000 + 30,000 = ₹5,10,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-159","question":"A firm with no opening stock produces 10,000 units and sells 8,000. Fixed manufacturing overhead is ₹1,50,000. How do profits under absorption costing and marginal costing compare?","options":["Absorption profit higher by ₹30,000","Marginal profit higher by ₹30,000","Absorption profit higher by ₹37,500","Both profits are equal"],"answer":0,"explanation":"Absorption costing carries ₹15 of fixed overhead per unit (1,50,000 ÷ 10,000) into the 2,000 units of closing stock, deferring ₹30,000 to the next period, so its profit is higher by ₹30,000. Spreading the overhead over units sold gives the wrong ₹37,500.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-160","question":"Machine hours are limited to 8,000. Product X gives a contribution of ₹40 a unit and needs 4 hours; product Y gives ₹30 and needs 2 hours. Maximum demand is 1,500 units of X and 3,000 of Y. What is the maximum contribution?","options":["₹90,000","₹1,20,000","₹1,50,000","₹1,10,000"],"answer":3,"explanation":"Contribution per hour: X ₹10, Y ₹15, so make Y first: 3,000 units use 6,000 hours (₹90,000). The remaining 2,000 hours make 500 units of X (₹20,000). Total ₹1,10,000. Ranking by contribution per unit (X first) gives only ₹90,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-161","question":"A component costs ₹42 a unit in variable cost to make, plus ₹10 a unit of allocated fixed overhead that will continue whether it is made or bought. A supplier offers it at ₹48. What should the firm do?","options":["Buy, saving ₹4 a unit","Make, saving ₹6 a unit","Buy, since the full cost of ₹52 exceeds ₹48","It is indifferent"],"answer":1,"explanation":"The fixed overhead is unavoidable, so only the variable ₹42 is relevant. Buying at ₹48 costs ₹6 a unit more, so make. Comparing ₹48 with the full cost of ₹52 is the classic mistake.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-162","question":"A firm has idle capacity. Its normal price is ₹100 a unit and variable cost ₹70. A customer offers to buy 2,000 extra units at ₹80; fixed costs will not change. What is the effect of accepting?","options":["Profit rises by ₹20,000","Profit falls by ₹40,000","No change in profit","Profit rises by ₹60,000"],"answer":0,"explanation":"Each extra unit adds ₹80 − ₹70 = ₹10 of contribution: 2,000 × 10 = ₹20,000. With spare capacity and no effect on regular prices, the order is worth taking.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-163","question":"As output increases within the relevant range, fixed cost per unit:","options":["Rises","Stays constant","Rises and then falls","Falls"],"answer":3,"explanation":"Total fixed cost is constant, so spreading it over more units lowers the cost per unit. Variable cost per unit stays constant.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-164","question":"A firm's margin of safety is 25% of sales and its P/V ratio is 40%. Sales are ₹8,00,000. What is the profit?","options":["₹80,000","₹2,00,000","₹3,20,000","₹1,00,000"],"answer":0,"explanation":"Profit = margin of safety × P/V ratio = (25% × 8,00,000) × 40% = 2,00,000 × 40% = ₹80,000; i.e. profit is 10% of sales.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-165","question":"Selling price is ₹40 a unit, variable cost ₹24 and fixed costs ₹1,60,000. If the selling price is cut by 10%, by what percentage does the break-even point in units rise?","options":["10% increase","33.33% increase","25% increase","16.67% increase"],"answer":1,"explanation":"Old contribution ₹16 → BEP 10,000 units. New price ₹36 → contribution ₹12 → BEP 13,333 units, a rise of 33.33%. A 10% price cut wipes out 25% of the contribution, so the BEP jumps far more than 10%.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-166","question":"Total cost is ₹1,80,000 at 10,000 units and ₹2,30,000 at 15,000 units. Using the high–low method, what is the expected total cost at 12,000 units?","options":["₹2,16,000","₹1,84,000","₹2,04,000","₹2,00,000"],"answer":3,"explanation":"Variable cost = 50,000 ÷ 5,000 = ₹10 a unit; fixed cost = 1,80,000 − 1,00,000 = 80,000. At 12,000 units: 80,000 + 1,20,000 = ₹2,00,000. Scaling the whole cost up by 20% gives ₹2,16,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-167","question":"A firm sells 10,000 units at ₹60 with variable cost ₹36 and fixed costs ₹1,80,000. If variable cost rises by 10% and the price is unchanged, how many units must it sell to keep the same profit?","options":["11,765 units","11,000 units","10,909 units","12,500 units"],"answer":0,"explanation":"Current profit = 10,000 × 24 − 1,80,000 = 60,000. New variable cost ₹39.60, contribution ₹20.40. Units = (1,80,000 + 60,000) ÷ 20.40 ≈ 11,765.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-168","question":"Plan A has fixed costs of ₹2,00,000 and variable costs of 60% of sales. Plan B has fixed costs of ₹3,20,000 and variable costs of 40% of sales. At what level of sales are the two plans equally profitable?","options":["₹3,00,000","₹8,00,000","₹5,00,000","₹6,00,000"],"answer":3,"explanation":"Equal profit when the extra fixed cost of B equals its extra contribution: (3,20,000 − 2,00,000) ÷ (60% − 40%) = ₹6,00,000. Above this, B (higher P/V ratio) is better. ₹5,00,000 and ₹8,00,000 are the break-even points of A and B.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-169","question":"Budgeted overheads are ₹4,80,000 for 60,000 budgeted machine hours. Actual hours worked are 64,000 and actual overheads ₹5,00,000. What is the over- or under-absorption?","options":["Over-absorbed ₹12,000","Under-absorbed ₹20,000","Under-absorbed ₹12,000","Over-absorbed ₹32,000"],"answer":0,"explanation":"Rate = ₹8 an hour; absorbed = 64,000 × 8 = 5,12,000; actual 5,00,000. More was absorbed than incurred: over-absorbed by ₹12,000. Comparing actual with budget gives the misleading ₹20,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-170","question":"A factory had 900 workers at the start of the year and 1,100 at the end; 50 workers left during the year. What is the labour turnover rate by the separation method?","options":["5%","4.55%","5.56%","10%"],"answer":0,"explanation":"Average workers = (900 + 1,100) ÷ 2 = 1,000; turnover = 50 ÷ 1,000 = 5%. Dividing by the closing or opening figure gives 4.55% or 5.56%.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-171","question":"Annual demand is 9,000 units, the cost of placing an order ₹240, the unit price ₹60 and the annual carrying cost 20% of the unit price. What is the economic order quantity?","options":["600 units","849 units","300 units","1,200 units"],"answer":0,"explanation":"Carrying cost = 20% × 60 = ₹12 a unit a year. EOQ = √(2 × 9,000 × 240 ÷ 12) = √3,60,000 = 600 units. Using a ₹6 carrying cost (10%) gives 849.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-172","question":"Maximum usage is 500 units a day and the maximum lead time 12 days; normal usage is 400 units a day and the normal lead time 10 days. What is the minimum stock level?","options":["4,000 units","6,000 units","1,500 units","2,000 units"],"answer":3,"explanation":"Re-order level = 500 × 12 = 6,000. Minimum level = re-order level − normal usage × normal lead time = 6,000 − 4,000 = 2,000 units.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-173","question":"Opening stock is 100 units at ₹20; 200 units are bought at ₹23; then 250 units are issued. How does the closing stock under FIFO compare with that under the weighted average method?","options":["₹50 higher under FIFO","₹50 lower under FIFO","₹150 higher under FIFO","No difference"],"answer":0,"explanation":"FIFO: the 50 units left are from the ₹23 lot = ₹1,150. Weighted average rate = (2,000 + 4,600) ÷ 300 = ₹22, so closing = 50 × 22 = ₹1,100. FIFO is ₹50 higher (prices are rising).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-174","question":"Which of these is a period cost that is not included in inventory?","options":["Direct labour","Factory rent","Raw materials","Salesmen's commission"],"answer":3,"explanation":"Selling costs are charged to the period in which they arise; materials, labour and factory overheads are product costs carried in inventory.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-175","question":"The P/V ratio is 25%, fixed costs ₹1,50,000 and sales ₹8,00,000. What is the profit?","options":["₹2,00,000","₹6,50,000","₹1,00,000","₹50,000"],"answer":3,"explanation":"Contribution = 25% × 8,00,000 = 2,00,000; profit = 2,00,000 − 1,50,000 = ₹50,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-176","question":"The standard price of a material is ₹20 a kg. 5,000 kg are bought and used at ₹22 a kg. What is the material price variance?","options":["₹10,000 (F)","₹10,000 (A)","₹11,000 (A)","₹9,091 (A)"],"answer":1,"explanation":"Price variance = AQ × (SP − AP) = 5,000 × (20 − 22) = −10,000, adverse because more was paid than standard.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-177","question":"The standard is 2 kg of material at ₹20 a kg per unit. 2,400 units are produced using 5,000 kg bought at ₹22 a kg. What is the material usage variance?","options":["₹4,400 (A)","₹4,000 (F)","₹4,000 (A)","₹8,000 (A)"],"answer":2,"explanation":"Standard quantity for actual output = 2,400 × 2 = 4,800 kg. Usage variance = SP × (SQ − AQ) = 20 × (4,800 − 5,000) = ₹4,000 adverse. Valuing at the actual price (₹22) gives ₹4,400, which wrongly mixes in price.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-178","question":"The standard is 2 kg at ₹20 a kg per unit. 2,400 units are made using 5,000 kg costing ₹22 a kg. What is the material cost variance?","options":["₹6,000 (A)","₹14,000 (A)","₹14,000 (F)","₹10,000 (A)"],"answer":1,"explanation":"Standard cost = 4,800 × 20 = 96,000; actual cost = 5,000 × 22 = 1,10,000. Cost variance = ₹14,000 adverse = price variance ₹10,000 (A) + usage variance ₹4,000 (A).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-179","question":"Standard: 3 labour hours per unit at ₹40 an hour. 1,000 units are produced; 3,300 hours are paid at ₹42, of which 100 hours were idle because of a machine breakdown. What is the labour efficiency variance?","options":["₹12,000 (A)","₹8,000 (A)","₹8,400 (A)","₹4,000 (A)"],"answer":1,"explanation":"Hours worked = 3,300 − 100 = 3,200; standard hours = 3,000. Efficiency = 40 × (3,000 − 3,200) = ₹8,000 (A). Idle time (100 × 40 = ₹4,000 A) and rate (3,300 × 2 = ₹6,600 A) are separate; together they make up the total ₹18,600 (A). Ignoring idle time gives ₹12,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-180","question":"The standard mix is 60% material A at ₹50 a kg and 40% material B at ₹30 a kg. The actual input is 1,000 kg: 650 kg of A and 350 kg of B. What is the material mix variance?","options":["₹1,000 (F)","₹4,000 (A)","₹1,000 (A)","₹2,500 (A)"],"answer":2,"explanation":"Revised standard quantities for 1,000 kg: A 600, B 400. Mix variance = SP × (RSQ − AQ): A 50 × (600 − 650) = −2,500; B 30 × (400 − 350) = +1,500. Net ₹1,000 adverse: more of the dearer material was used.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-181","question":"Budgeted fixed overhead is ₹1,20,000 for 12,000 units (₹10 a unit). Actual output is 11,000 units and actual fixed overhead ₹1,26,000. What is the fixed overhead volume variance?","options":["₹6,000 (A)","₹16,000 (A)","₹10,000 (F)","₹10,000 (A)"],"answer":3,"explanation":"Volume variance = rate × (actual output − budgeted output) = 10 × (11,000 − 12,000) = ₹10,000 (A). The ₹6,000 (A) is the expenditure variance; together they make the total ₹16,000 (A).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-182","question":"The standard selling price is ₹50 a unit. 10,000 units are actually sold at ₹48. What is the sales price variance?","options":["₹20,000 (F)","₹20,000 (A)","₹19,200 (A)","₹2,000 (A)"],"answer":1,"explanation":"Sales price variance = actual units × (actual price − standard price) = 10,000 × (48 − 50) = ₹20,000 adverse.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-183","question":"Budgeted sales were 12,000 units at ₹50 with a standard contribution of ₹15 a unit; actual sales were 10,000 units. Under marginal costing, what is the sales volume variance?","options":["₹1,00,000 (A)","₹30,000 (A)","₹30,000 (F)","₹24,000 (A)"],"answer":1,"explanation":"Under marginal costing the volume variance is valued at standard contribution: (10,000 − 12,000) × 15 = ₹30,000 (A). Valuing it at the selling price (₹1,00,000) overstates the effect on profit.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-184","question":"A cost variance is favourable when:","options":["Actual cost exceeds standard cost","Actual output is below budget","Actual cost is below standard cost","The standard is revised upward"],"answer":2,"explanation":"Spending less than the standard for the actual output is favourable; spending more is adverse.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-185","question":"At 10,000 units the budget shows variable costs ₹2,00,000, semi-variable costs ₹80,000 (50% fixed) and fixed costs ₹1,00,000. What is the flexible budget cost at 12,000 units?","options":["₹4,56,000","₹4,36,000","₹4,28,000","₹3,80,000"],"answer":2,"explanation":"Variable: 2,00,000 × 1.2 = 2,40,000. Semi-variable: 40,000 fixed + 40,000 × 1.2 = 88,000. Fixed 1,00,000. Total ₹4,28,000. Treating all semi-variable cost as variable gives ₹4,36,000; scaling everything gives ₹4,56,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-186","question":"Sales are ₹1,00,000 in January, ₹1,20,000 in February and ₹1,50,000 in March. 20% of sales are for cash; credit sales are collected 50% in the next month and 50% in the month after. What are the total cash receipts in March?","options":["₹1,20,000","₹1,10,000","₹1,35,000","₹1,18,000"],"answer":3,"explanation":"March cash sales 30,000; half of February's credit sales (96,000) = 48,000; half of January's credit sales (80,000) = 40,000. Total ₹1,18,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-187","question":"Budgeted sales are 20,000 units. Finished-goods stock is 3,000 units at the start and should be 4,500 at the end. Each unit needs 2 kg of material; material stock is 6,000 kg at the start and should be 8,000 kg at the end. How much material must be purchased?","options":["45,000 kg","43,000 kg","40,000 kg","41,000 kg"],"answer":0,"explanation":"Production = 20,000 + 4,500 − 3,000 = 21,500 units → 43,000 kg needed. Purchases = 43,000 + 8,000 − 6,000 = 45,000 kg. 43,000 kg ignores the material stock change; 40,000 kg budgets on sales instead of production.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-188","question":"Zero-based budgeting is best described as:","options":["Last year's figures adjusted for inflation","A budget that changes with the level of activity","A rolling budget updated every quarter","A budget in which every activity must be justified afresh, starting from zero"],"answer":3,"explanation":"ZBB ignores the previous year's base; each activity must be justified by its costs and benefits. A budget that changes with activity is a flexible budget.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-189","question":"A proprietor's household electricity bill paid from the business bank account is recorded as drawings, not as an expense of the business. Which concept requires this?","options":["Going concern","Money measurement","Business entity","Accrual"],"answer":2,"explanation":"The business entity concept treats the business as separate from its owner, so the owner's personal expenses are drawings.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-190","question":"Under Ind AS 115, a company sells 1,000 units at ₹500 each with a right of return; it expects 5% of the goods to be returned. Each unit costs ₹300. How much revenue is recognised?","options":["₹5,00,000","₹4,75,000","₹4,85,000","₹2,85,000"],"answer":1,"explanation":"Revenue is recognised only for the consideration the company expects to keep: 950 units × 500 = ₹4,75,000. A refund liability of ₹25,000 and an asset for the right to recover goods (50 × 300 = ₹15,000) are also recognised.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-191","question":"Under Ind AS 115, a company sells a machine together with two years of servicing for ₹1,20,000. Sold separately, the machine would fetch ₹1,00,000 and the servicing ₹50,000. How much revenue is allocated to the machine?","options":["₹1,00,000","₹70,000","₹80,000","₹1,20,000"],"answer":2,"explanation":"The price is allocated in proportion to stand-alone selling prices: 1,20,000 × 1,00,000/1,50,000 = ₹80,000 (servicing ₹40,000, recognised over two years). Giving the servicing its full ₹50,000 and the machine the remainder (₹70,000) is not the relative method.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-192","question":"A customer has sued a company. Its lawyers say a loss is possible but not probable, and the amount cannot be estimated reliably. How is this treated under Ind AS 37?","options":["Disclosed as a contingent liability in the notes","A provision is recognised","Ignored completely","Recognised as both a liability and an asset"],"answer":0,"explanation":"A provision needs a probable outflow and a reliable estimate. A possible obligation is disclosed as a contingent liability; only a remote one is ignored.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-193","question":"Under Ind AS 10, how many of these are adjusting events for a company whose year ends on 31 March? (1) A debtor owing money on 31 March is declared bankrupt in April. (2) A warehouse is destroyed by fire in May, before the accounts are approved. (3) An equity dividend is proposed after the year end and is shown as a liability at year end. (4) A court case pending at year end is settled in April, confirming an obligation that existed on 31 March.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) Adjusting: it confirms the debt was bad at year end. (2) Non-adjusting: the fire is a new event. (3) Wrong treatment: a dividend proposed after year end is not a liability at year end, so it is not an adjusting event. (4) Adjusting. Two are adjusting events.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-194","question":"Which of these is an example of 'substance over form'?","options":["Recording goods at cost, not market value","Recording only transactions that can be measured in money","Assuming the business will continue for the foreseeable future","A lessee recognising a right-of-use asset for a machine it does not legally own"],"answer":3,"explanation":"Under Ind AS 116 the lessee controls the asset's use for the lease term, so the economic substance (an asset and a lease liability) is recorded despite the legal form (ownership stays with the lessor).","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-195","question":"A company changes its inventory cost formula from FIFO to weighted average to give more relevant information. How does Ind AS 8 require this to be applied?","options":["Prospectively only","Retrospectively, restating comparatives, unless impracticable","By disclosure only, with no adjustment","By charging the whole cumulative effect to the current year's profit without restating"],"answer":1,"explanation":"A change in the cost formula is a change in accounting policy. Ind AS 8 requires retrospective application, adjusting opening equity and comparatives, unless that is impracticable.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-196","question":"An asset's carrying amount is ₹10,00,000. Its fair value less costs of disposal is ₹7,80,000 and its value in use is ₹8,20,000. What impairment loss is recognised under Ind AS 36?","options":["₹2,20,000","₹1,80,000","₹2,00,000","Nil"],"answer":1,"explanation":"Recoverable amount is the higher of the two, ₹8,20,000. Impairment = 10,00,000 − 8,20,000 = ₹1,80,000. Using the lower figure gives ₹2,20,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-197","question":"A standard cost is:","options":["A predetermined cost of what a unit should cost under efficient conditions","The actual historical cost of the last batch","The market price of the finished product","The average cost of all competitors"],"answer":0,"explanation":"Standards are set in advance; comparing them with actual costs gives the variances used for control.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-198","question":"Standard: 2 machine hours per unit and variable overhead of ₹15 an hour. 4,000 units are produced in 8,400 hours, and actual variable overhead is ₹1,30,000. What is the variable overhead expenditure variance?","options":["₹10,000 (A)","₹6,000 (A)","₹4,000 (F)","₹4,000 (A)"],"answer":3,"explanation":"Expenditure variance = actual hours × standard rate − actual overhead = 8,400 × 15 − 1,30,000 = −4,000 (A). Efficiency = 15 × (8,000 − 8,400) = ₹6,000 (A). Total ₹10,000 (A).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-199","question":"In budgeting, the 'principal budget factor' (key factor) is:","options":["The factor that limits the organisation's activity, such as sales demand","The budget with the largest rupee amount","The fixed overhead budget","The cash budget"],"answer":0,"explanation":"The key factor limits activity, often sales demand but sometimes materials, labour or machine capacity, so it is budgeted first and the other budgets follow from it.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-200","question":"The standard labour rate is ₹50 an hour; 2,000 hours are paid at ₹48 an hour. What is the labour rate variance?","options":["₹4,000 (A)","₹96,000 (F)","₹4,000 (F)","₹3,840 (F)"],"answer":2,"explanation":"Rate variance = actual hours paid × (SR − AR) = 2,000 × (50 − 48) = ₹4,000, favourable because less was paid than standard.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-201","question":"Goods are sent on consignment by a manufacturer to an agent in another city. Until the agent sells them, who owns the goods?","options":["The consignor (the manufacturer)","The consignee (the agent)","The carrier while they are in transit, then the agent","The eventual buyer, from the date of dispatch"],"answer":0,"explanation":"A consignment is an agency arrangement: the consignee only holds and sells the goods for the consignor, so ownership stays with the consignor until a sale to a third party. That is why unsold goods with the agent appear in the consignor's closing stock.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-202","question":"1,000 units costing ₹200 each are sent on consignment. The consignor pays freight of ₹10,000 and the consignee pays unloading and carriage to his godown of ₹4,000; the consignee also spends ₹6,000 on advertising and selling. 800 units are sold. At what value is the unsold stock carried?","options":["₹40,000","₹42,000","₹44,000","₹42,800"],"answer":3,"explanation":"Unsold stock carries its cost plus a proportion of the expenses incurred to bring the goods to the place of sale (freight and the consignee's unloading and carriage), but not selling expenses: 200 × (200 + 14,000 ÷ 1,000) = 200 × 214 = ₹42,800. ₹44,000 wrongly loads the selling expenses; ₹42,000 picks up only the consignor's freight.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-203","question":"A consignee sells consigned goods for ₹5,00,000: ₹3,00,000 in cash and ₹2,00,000 on credit. He gets 5% ordinary commission and 2% del credere commission, both on total sales. ₹8,000 of the credit sales turn out to be bad. Ignoring expenses, how much does the consignor finally receive for these sales?","options":["₹4,57,000","₹4,65,000","₹4,71,000","₹4,75,000"],"answer":1,"explanation":"With del credere commission the consignee guarantees the debts, so the ₹8,000 bad debt is his loss, not the consignor's. Consignor gets 5,00,000 − 7% × 5,00,000 = ₹4,65,000. ₹4,57,000 also deducts the bad debt; ₹4,71,000 applies the 2% to credit sales only; ₹4,75,000 forgets the del credere commission.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-204","question":"A and B enter a joint venture sharing profits 3 : 2. A buys goods for ₹60,000 and pays ₹4,000 of expenses. B sells goods for ₹90,000, pays ₹6,000 of expenses and takes over the unsold goods at an agreed ₹5,000. B holds all the cash from sales. How much must B pay A in final settlement?","options":["₹64,000","₹76,000","₹74,000","₹79,000"],"answer":3,"explanation":"Venture profit = sales 90,000 + stock taken over 5,000 − costs (60,000 + 4,000 + 6,000) = ₹25,000; A's 3/5 share = ₹15,000. A must get back his outlay ₹64,000 plus his profit ₹15,000 = ₹79,000. Forgetting the stock taken over gives profit ₹20,000 and ₹76,000; giving A only 2/5 gives ₹74,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-205","question":"Under a hire-purchase agreement, when does ownership of the asset normally pass to the hirer?","options":["When the last instalment is paid","When the agreement is signed","When the asset is delivered","When the down payment is made"],"answer":0,"explanation":"The hirer gets possession and use at once but remains a bailee; title passes only when all instalments have been paid (or the purchase option is exercised). That is the key difference from an instalment sale, where ownership passes immediately.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-206","question":"A machine with a cash price of ₹1,20,000 is bought on hire purchase: ₹20,700 down and three equal year-end instalments of ₹39,930. Interest is 10% a year on the outstanding cash price. How much interest is charged in year 2?","options":["₹9,930","₹3,630","₹6,830","₹6,930"],"answer":3,"explanation":"Opening balance 99,300. Year 1: interest 9,930, instalment 39,930 → balance 69,300. Year 2: interest 10% × 69,300 = ₹6,930 (year 3 is ₹3,630, which with 36,300 of principal exactly clears the last instalment). ₹6,830 just averages total interest of ₹20,490 over three years.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-207","question":"Same hire purchase: cash price ₹1,20,000, ₹20,700 down, instalments of ₹39,930 at each year end, 10% interest; the hirer depreciates the machine at 10% a year on the written-down value. The first instalment is paid, but the second is not, and the vendor repossesses the machine at the end of year 2. What loss does the hirer record on repossession?","options":["₹27,900","₹20,970","₹19,770","₹43,770"],"answer":1,"explanation":"Book value of the machine after two years = 1,20,000 × 0.9 × 0.9 = ₹97,200. Amount owed to the vendor = balance 69,300 + year-2 interest 6,930 = ₹76,230, which is cancelled by the repossession. Loss = 97,200 − 76,230 = ₹20,970. Leaving out year-2 interest gives ₹27,900; straight-line depreciation gives ₹19,770; ignoring depreciation gives ₹43,770.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-208","question":"Opening stock is 200 units at ₹50. Purchases are 300 units at ₹55 and then 400 units at ₹60. 650 units are sold during the period. What is the closing stock under FIFO (periodic)?","options":["₹15,000","₹14,028","₹12,750","₹13,750"],"answer":0,"explanation":"Closing stock is 900 − 650 = 250 units. Under FIFO the earliest units are sold first, so the closing 250 come from the latest purchase at ₹60 = ₹15,000. ₹14,028 is the periodic weighted average (50,500 ÷ 900 × 250); ₹12,750 values the stock from the oldest layers.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-209","question":"Opening stock 100 units at ₹40. 1 March: bought 300 at ₹48. 5 March: issued 200. 10 March: bought 200 at ₹52. 15 March: issued 250. What is the closing stock under the perpetual weighted-average method?","options":["₹7,350","₹7,200","₹7,800","₹7,500"],"answer":0,"explanation":"After 1 March: 400 units for ₹18,400 (average ₹46). Issue 200 → 200 left at ₹46 = ₹9,200. After 10 March: 400 units for ₹19,600 (average ₹49). Issue 250 → 150 left × ₹49 = ₹7,350. ₹7,200 uses one periodic average of ₹48; ₹7,800 is FIFO (150 × ₹52).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-210","question":"Prices of a firm's inventory rose steadily through the year. How many of these statements are correct? (1) FIFO shows a higher closing stock than weighted average. (2) FIFO shows a lower cost of goods sold than weighted average. (3) Ind AS 2 allows LIFO if it is applied consistently. (4) Weighted average smooths out the effect of price changes on cost of goods sold.","options":["Two","Four","Three","One"],"answer":2,"explanation":"(1), (2) and (4) are correct: with rising prices FIFO leaves the newer, dearer units in stock and charges the older, cheaper units to cost of sales, while weighted average blends them. (3) is wrong: Ind AS 2 permits only FIFO and weighted average (or specific identification), not LIFO.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-211","question":"10,000 units are put into a process at a material cost of ₹1,50,000; conversion costs are ₹1,08,000. Normal loss is 10% of input and is sold as scrap at ₹6 a unit. Actual output is 8,800 units. What is the value of the abnormal loss transferred to the abnormal loss account?","options":["₹4,400","₹5,733","₹5,600","₹5,864"],"answer":2,"explanation":"Cost per unit of normal output = (2,58,000 − scrap 6,000) ÷ 9,000 = ₹28. Abnormal loss = 9,000 − 8,800 = 200 units × ₹28 = ₹5,600. ₹4,400 is the net charge to profit and loss after crediting scrap of ₹6 a unit; ₹5,733 ignores the scrap value; ₹5,864 divides by actual output.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-212","question":"Opening work-in-progress is 2,000 units, 40% complete as to conversion. 18,000 units are started. Closing work-in-progress is 3,000 units, 60% complete as to conversion. There are no losses. What are the equivalent units for conversion under the FIFO method?","options":["18,000","18,800","16,800","19,600"],"answer":0,"explanation":"Completed = 2,000 + 18,000 − 3,000 = 17,000, of which 15,000 were started and finished this period. FIFO counts only this period's work: finishing opening WIP 2,000 × 60% = 1,200 + 15,000 + closing 3,000 × 60% = 1,800 → 18,000. Weighted average would give 17,000 + 1,800 = 18,800; ignoring the work on opening WIP gives 16,800.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-213","question":"A joint cost of ₹3,00,000 produces 6,000 units of A and 4,000 units of B. B is sold at split-off for ₹45 a unit. A is processed further at a cost of ₹60,000 and sold for ₹80 a unit. How much joint cost is apportioned to A on the net realisable value method?","options":["₹2,18,182","₹1,80,000","₹1,50,000","₹2,10,000"],"answer":3,"explanation":"NRV of A = 6,000 × 80 − 60,000 = ₹4,20,000; B = 4,000 × 45 = ₹1,80,000. A's share = 3,00,000 × 4,20,000 ÷ 6,00,000 = ₹2,10,000. ₹2,18,182 uses A's final sales value without deducting further processing; ₹1,80,000 uses physical units.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-214","question":"Under activity-based costing, set-up costs of ₹2,40,000 are driven by 80 set-ups and inspection costs of ₹1,50,000 by 500 inspections. Product X (1,000 units) needs 30 set-ups and 100 inspections. What is X's overhead per unit under ABC?","options":["₹60","₹120","₹90","₹30"],"answer":1,"explanation":"Rates: ₹3,000 per set-up and ₹300 per inspection. X: 30 × 3,000 + 100 × 300 = ₹1,20,000 ÷ 1,000 units = ₹120. ₹90 and ₹30 pick up only one of the two pools.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-215","question":"In activity-based costing, which of these is a batch-level activity?","options":["Setting up a machine before each production run","Power consumed while the machine runs","Insurance of the factory building","Designing a new product"],"answer":0,"explanation":"Set-up cost is incurred once per batch, whatever the batch size. Machine power is unit-level (varies with each unit), factory insurance is facility-sustaining, and product design is product-sustaining.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-216","question":"A division earns ₹6,00,000 on investment of ₹40,00,000; the firm's cost of capital is 12%. The manager is offered a project needing ₹10,00,000 that will earn ₹1,40,000 a year. What happens to the division's ROI and residual income if the project is accepted?","options":["ROI rises to 15.4% and residual income rises by ₹20,000","ROI falls to 14.8% and residual income falls by ₹20,000","ROI is unchanged and residual income rises by ₹1,40,000","ROI falls to 14.8% while residual income rises by ₹20,000"],"answer":3,"explanation":"ROI moves from 15% to 7,40,000 ÷ 50,00,000 = 14.8%. Residual income moves from 6,00,000 − 4,80,000 = ₹1,20,000 to 7,40,000 − 6,00,000 = ₹1,40,000, a rise of ₹20,000. The project earns 14%, above the 12% cost of capital, so it adds value; a manager judged on ROI would wrongly reject it, the goal-congruence problem RI avoids.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-217","question":"In responsibility accounting, a segment whose manager is accountable for costs, revenues and the capital invested in it is called a:","options":["Cost centre","Investment centre","Revenue centre","Profit centre"],"answer":1,"explanation":"A cost centre answers for costs only, a revenue centre for revenue, a profit centre for both, and an investment centre additionally for the assets employed, so it is judged on ROI or residual income.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-218","question":"Division A makes a component with a variable cost of ₹60 and can sell all its output outside at ₹100; ₹5 a unit of selling costs is saved on internal transfers. A is working at full capacity. What is the minimum transfer price A should accept from Division B?","options":["₹100","₹60","₹95","₹65"],"answer":2,"explanation":"At full capacity, each unit transferred is a lost outside sale, so the minimum price = variable cost + lost contribution = market price less costs saved = 100 − 5 = ₹95. ₹60 would be right only with spare capacity.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-219","question":"The profit and loss account balance rose by ₹80,000 during the year after: transfer to general reserve ₹50,000; depreciation ₹40,000; goodwill written off ₹10,000; and a profit of ₹25,000 on sale of land credited to it. What are the funds from operations?","options":["₹2,05,000","₹1,05,000","₹1,55,000","₹1,15,000"],"answer":2,"explanation":"Start from the rise in retained profit and add back appropriations and non-fund charges, then remove non-operating gains: 80,000 + 50,000 + 40,000 + 10,000 − 25,000 = ₹1,55,000. Adding the land profit instead of deducting it gives ₹2,05,000; forgetting the reserve transfer gives ₹1,05,000; forgetting depreciation gives ₹1,15,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-220","question":"Current assets were ₹5,00,000 at the start and ₹6,20,000 at the end of the year; current liabilities were ₹2,40,000 and ₹3,10,000. What change in working capital appears in the schedule of changes in working capital?","options":["Increase of ₹1,20,000","Decrease of ₹50,000","Increase of ₹1,90,000","Increase of ₹50,000"],"answer":3,"explanation":"Working capital moved from 5,00,000 − 2,40,000 = ₹2,60,000 to 6,20,000 − 3,10,000 = ₹3,10,000, an increase of ₹50,000. ₹1,20,000 looks only at current assets and ignores the ₹70,000 rise in current liabilities.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-221","question":"A firm's super profit is expected to be ₹60,000 a year for the next 5 years. Using the annuity method with a 10% discount rate (5-year annuity factor 3.7908), what is goodwill?","options":["₹3,00,000","₹6,00,000","₹1,90,194","₹2,27,448"],"answer":3,"explanation":"Goodwill = present value of the super-profit stream = 60,000 × 3.7908 = ₹2,27,448. ₹3,00,000 is five years' purchase without discounting; ₹6,00,000 capitalises the super profit at 10% as if it were perpetual; ₹1,90,194 uses a 4-year factor (3.1699).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-222","question":"A company's assets total ₹50,00,000, including goodwill fairly valued at ₹4,00,000 and preliminary expenses not written off of ₹1,00,000. Outside liabilities are ₹12,00,000 and 10% preference share capital is ₹6,00,000. There are 2,00,000 equity shares. What is the intrinsic (net assets) value of an equity share?","options":["₹16.00","₹18.50","₹15.50","₹13.50"],"answer":2,"explanation":"Net assets for equity = 50,00,000 − preliminary expenses 1,00,000 (fictitious) − liabilities 12,00,000 − preference capital 6,00,000 = ₹31,00,000 ÷ 2,00,000 = ₹15.50. Keeping preliminary expenses gives ₹16; not deducting preference capital gives ₹18.50; also excluding the fairly valued goodwill gives ₹13.50.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-223","question":"A company with 1,00,000 fully paid equity shares of ₹100 expects profit after tax of ₹9,00,000 and transfers 20% of it to reserves, distributing the rest. The normal rate of dividend in the industry is 9%. What is the value of a share on the dividend-yield basis?","options":["₹80","₹100","₹72","₹64"],"answer":0,"explanation":"Dividend per share = 9,00,000 × 80% ÷ 1,00,000 = ₹7.20, a 7.2% rate on ₹100. Value = (7.2 ÷ 9) × 100 = ₹80. ₹100 uses the full 9% earnings rate and ignores the retention; ₹72 confuses the dividend with the value; ₹64 deducts the 20% retention twice.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-224","question":"T Ltd takes over S Ltd, which has 30,000 equity shares. For every 3 shares of S, T issues 2 equity shares of ₹10 each at ₹15, and it also pays ₹5 in cash for every share of S. What is the purchase consideration?","options":["₹3,50,000","₹4,50,000","₹3,00,000","₹8,25,000"],"answer":1,"explanation":"Shares issued = 30,000 × 2/3 = 20,000 × ₹15 = ₹3,00,000; cash = 30,000 × ₹5 = ₹1,50,000; total ₹4,50,000. Valuing the shares at par gives ₹3,50,000; leaving out the cash gives ₹3,00,000; inverting the ratio (3 for 2) gives ₹8,25,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-225","question":"How many of these statements about accounting for business combinations in India are correct? (1) Under Ind AS 103, a combination not under common control uses the acquisition method, with identifiable assets and liabilities at fair value. (2) Under Ind AS 103, a combination of entities under common control uses the pooling-of-interests method at carrying amounts. (3) Goodwill arising under Ind AS 103 is amortised over a maximum of ten years. (4) Under AS 14, the purchase method lets the transferee record assets either at their existing carrying amounts or at fair values.","options":["Two","Four","Three","One"],"answer":2,"explanation":"(1), (2) and (4) are correct. (3) is wrong: under Ind AS, goodwill is not amortised but tested for impairment at least annually.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-226","question":"Under Ind AS 116, how does a lessee normally account for a five-year lease of office space (not short-term, not low-value)?","options":["It charges the rent to profit and loss as an operating lease, with nothing on the balance sheet","It records the full building as its own fixed asset","It recognises a right-of-use asset and a lease liability","It discloses the lease only in the notes"],"answer":2,"explanation":"Ind AS 116 removed the operating/finance distinction for lessees. Apart from the short-term and low-value exemptions, every lease brings a right-of-use asset and a lease liability onto the balance sheet.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-227","question":"A lessee signs a 3-year lease with annual payments of ₹1,00,000 at each year end. The discount rate is 10% (3-year annuity factor 2.4869) and the lessee pays initial direct costs of ₹5,000. What is the right-of-use asset at commencement under Ind AS 116?","options":["₹2,48,690","₹3,05,000","₹2,53,690","₹3,00,000"],"answer":2,"explanation":"Lease liability = PV of payments = 1,00,000 × 2.4869 = ₹2,48,690. The right-of-use asset = lease liability + initial direct costs = ₹2,53,690. ₹2,48,690 forgets the direct costs; ₹3,05,000 uses undiscounted payments.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-228","question":"Same lease: payments of ₹1,00,000 at each year end for 3 years, 10% rate, lease liability ₹2,48,690 and right-of-use asset ₹2,53,690, depreciated straight-line over the lease term. What total expense does the lessee recognise in profit and loss in year 1?","options":["₹1,00,000","₹1,07,766","₹99,432","₹1,09,432"],"answer":3,"explanation":"Depreciation = 2,53,690 ÷ 3 = ₹84,563; interest = 10% × 2,48,690 = ₹24,869 (on the opening liability, since payment is at year end); total ₹1,09,432. ₹1,00,000 is the old operating-lease rent; ₹1,07,766 depreciates only the lease liability; ₹99,432 computes interest after deducting the year-end payment.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-229","question":"A lease liability of ₹2,48,690 is recognised at 10%. The first annual payment of ₹1,00,000 is made at the end of year 1. What is the lease liability at the end of year 1?","options":["₹1,48,690","₹1,73,559","₹1,65,793","₹2,73,559"],"answer":1,"explanation":"Closing liability = opening + interest − payment = 2,48,690 + 24,869 − 1,00,000 = ₹1,73,559. ₹1,48,690 forgets the interest; ₹1,65,793 simply takes two-thirds of the opening amount; ₹2,73,559 forgets the payment.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-230","question":"A head office invoices goods to its branch at cost plus 25%. Branch opening stock is ₹50,000 and closing stock ₹75,000 (both at invoice price); goods sent during the year are ₹5,00,000 at invoice price. All goods are sold at invoice price. What is the branch's true gross profit?","options":["₹1,00,000","₹95,000","₹1,18,750","₹75,000"],"answer":1,"explanation":"Goods sold at invoice price = 50,000 + 5,00,000 − 75,000 = ₹4,75,000. Loading included = 25/125 = 20% of invoice price, so true profit = 4,75,000 × 20% = ₹95,000. ₹1,00,000 is the loading on goods sent, not sold; ₹1,18,750 takes 25% of the invoice price.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-231","question":"Goods are invoiced to a branch at cost plus 33⅓%. The branch's closing stock is ₹48,000 at invoice price. How much stock reserve must be created to remove the unrealised profit?","options":["₹16,000","₹12,000","₹36,000","₹9,600"],"answer":1,"explanation":"A mark-up of one-third on cost equals one-quarter of the invoice price: 48,000 × 1/4 = ₹12,000 (cost is ₹36,000). ₹16,000 wrongly applies 33⅓% to the invoice price.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-232","question":"A lease of a mine gives the landlord a royalty of ₹5 a tonne with a minimum rent of ₹50,000 a year. Short workings can be recouped from excess royalty in the next two years only. Output is 6,000 tonnes in year 1, 9,000 in year 2 and 14,000 in year 3. Short workings are recouped in the order they arose. How much is paid to the landlord in year 3?","options":["₹50,000","₹45,000","₹70,000","₹65,000"],"answer":0,"explanation":"Year 1: royalty 30,000, pay 50,000, short working 20,000. Year 2: royalty 45,000, pay 50,000, short working 5,000 (no excess to recoup year 1's). Year 3: royalty 70,000, excess over minimum 20,000, which recoups year 1's 20,000 (its last chance); year 2's 5,000 waits for year 4. Payment = 70,000 − 20,000 = ₹50,000. ₹45,000 recoups 25,000, more than the excess allows.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-233","question":"Stock on 1 April was ₹80,000; purchases to the date of a fire were ₹4,00,000 and sales ₹5,00,000. Gross profit is 25% of sales. Salvage is worth ₹15,000. The stock is insured for ₹70,000 under a policy with an average clause. What is the claim?","options":["₹60,000","₹70,000","₹90,000","₹56,875"],"answer":0,"explanation":"Cost of sales = 5,00,000 × 75% = 3,75,000, so stock at the fire = 80,000 + 4,00,000 − 3,75,000 = ₹1,05,000. Loss = 1,05,000 − 15,000 = ₹90,000. Under-insured, so claim = 90,000 × 70,000 ÷ 1,05,000 = ₹60,000. ₹56,875 treats the 25% as a mark-up on cost; ₹70,000 and ₹90,000 ignore the average clause.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-234","question":"The standard time for a job is 10 hours and the worker finishes it in 8 hours. The hourly rate is ₹60. What does the worker earn under the Rowan premium plan?","options":["₹540","₹600","₹576","₹480"],"answer":2,"explanation":"Rowan bonus = (time saved ÷ standard time) × time taken × rate = (2 ÷ 10) × 8 × 60 = ₹96, so earnings = 480 + 96 = ₹576. ₹540 is the Halsey 50% plan (480 + 50% × 2 × 60); ₹600 pays the whole time saved.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-235","question":"The standard time for a job is 12 hours. At what actual time taken does a worker earn the same bonus under the Halsey plan (50% of time saved) and the Rowan plan?","options":["8 hours","6 hours","9 hours","4 hours"],"answer":1,"explanation":"Halsey bonus = 0.5 × (S − T) × R; Rowan bonus = (S − T) ÷ S × T × R. They are equal when T ÷ S = 0.5, i.e. T = 6 hours. Taking less time than this, Halsey pays more; taking more, Rowan pays more.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-236","question":"A product's annual demand is 30,000 units. Each production run costs ₹1,200 to set up, and holding one unit for a year costs ₹2. What is the economic batch quantity?","options":["6,000 units","4,243 units","8,485 units","3,000 units"],"answer":0,"explanation":"EBQ = √(2 × annual demand × set-up cost ÷ carrying cost per unit) = √(2 × 30,000 × 1,200 ÷ 2) = √3,60,00,000 = 6,000 units. Dropping the 2 gives 4,243; doubling inside the root wrongly gives 8,485.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-237","question":"A 40-seat bus makes 2 round trips a day on a route 25 km long (one way), 25 days a month, with average occupancy of 80%. How many passenger-kilometres does it run in a month?","options":["40,000","80,000","1,00,000","1,60,000"],"answer":1,"explanation":"Each round trip is 2 × 25 = 50 km, so 100 km a day and 2,500 km a month. Passengers carried on average = 40 × 80% = 32. Passenger-km = 32 × 2,500 = 80,000. 40,000 counts only one direction; 1,00,000 assumes full occupancy.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-238","question":"Service department S1 has costs of ₹27,000 and S2 ₹18,000 before inter-service charges. S1 gives 20% of its services to S2; S2 gives 50% of its services to S1; the rest go to production departments. Using simultaneous equations, what is S1's total cost to be distributed?","options":["₹40,000","₹36,000","₹27,000","₹45,000"],"answer":0,"explanation":"S1 = 27,000 + 0.5 S2 and S2 = 18,000 + 0.2 S1. Substituting: S1 = 27,000 + 9,000 + 0.1 S1, so 0.9 S1 = 36,000 and S1 = ₹40,000 (S2 = ₹26,000). ₹36,000 stops after one round of transfers; ₹45,000 adds all of S2's cost.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-239","question":"Profit as per cost accounts is ₹2,50,000. Overheads under-absorbed in the cost accounts are ₹15,000; interest received of ₹8,000 appears only in the financial accounts; depreciation is ₹40,000 in the financial accounts but ₹35,000 in the cost accounts; and closing stock is valued at ₹1,20,000 in the cost accounts but ₹1,10,000 in the financial accounts (opening stock is the same in both). What is the profit as per financial accounts?","options":["₹2,28,000","₹2,48,000","₹2,58,000","₹2,38,000"],"answer":0,"explanation":"Start with ₹2,50,000; deduct under-absorbed overheads 15,000 (an extra charge in the financial books); add interest 8,000; deduct the extra depreciation 5,000; deduct 10,000 because the lower closing stock in the financial books lowers profit: ₹2,28,000. Reversing the stock adjustment gives ₹2,48,000; ignoring it gives ₹2,38,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-240","question":"A club received subscriptions of ₹1,80,000 in cash during the year. This includes ₹10,000 for the previous year and ₹6,000 for the next year. Subscriptions of ₹14,000 for the current year are still outstanding, and ₹4,000 for the current year had been received in advance last year. What is subscription income for the year?","options":["₹1,82,000","₹1,80,000","₹1,78,000","₹1,88,000"],"answer":0,"explanation":"Income = 1,80,000 − 10,000 (last year) − 6,000 (next year) + 14,000 (outstanding) + 4,000 (received last year for this year) = ₹1,82,000. Forgetting last year's advance gives ₹1,78,000; treating this year's advance as income gives ₹1,88,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-241","question":"A draws a bill of ₹50,000 on B and discounts it with his bank. On maturity B dishonours it and the bank pays noting charges of ₹200. What entry does A pass?","options":["Bills Receivable A/c Dr ₹50,000 To B A/c ₹50,000","B A/c Dr ₹50,000 To Bills Receivable A/c ₹50,000","Bank A/c Dr ₹50,200 To B A/c ₹50,200","B A/c Dr ₹50,200 To Bank A/c ₹50,200"],"answer":3,"explanation":"The bank recovers the bill amount and noting charges from A, so A credits the bank and charges both to B, who is liable for them: B Dr ₹50,200, Bank Cr ₹50,200. Crediting Bills Receivable would be right only if A still held the bill.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-242","question":"On 1 September an investor buys 1,000 12% debentures of ₹100 each at ₹103 cum-interest. Interest is payable on 30 June and 31 December. At what cost are the debentures recorded in the investment account?","options":["₹1,03,000","₹97,000","₹1,01,000","₹1,05,000"],"answer":2,"explanation":"A cum-interest price includes interest accrued since the last payment date (1 July to 31 August, 2 months): 1,00,000 × 12% × 2/12 = ₹2,000. Cost = 1,03,000 − 2,000 = ₹1,01,000, and the ₹2,000 is a receivable recovered from the December interest. ₹97,000 deducts a full half-year's interest.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-243","question":"Under an internal reconstruction, 1,00,000 equity shares of ₹10 fully paid are reduced to ₹4 fully paid. The amount is used to write off a debit balance of ₹3,50,000 in the profit and loss account, goodwill of ₹1,50,000 and ₹80,000 of plant. What is transferred to capital reserve?","options":["₹1,00,000","₹2,50,000","₹20,000","₹1,70,000"],"answer":2,"explanation":"Capital reduction = 1,00,000 × (10 − 4) = ₹6,00,000. Used: 3,50,000 + 1,50,000 + 80,000 = ₹5,80,000. Balance ₹20,000 goes to capital reserve. ₹1,00,000 forgets the plant; ₹1,70,000 forgets the goodwill.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-244","question":"A firm expects a new product to sell at ₹500 and wants a profit margin of 20% on the selling price. Under target costing, what is the target cost?","options":["₹416.67","₹400","₹600","₹480"],"answer":1,"explanation":"Target cost = target price − required profit = 500 − 20% × 500 = ₹400. ₹416.67 treats the 20% as a mark-up on cost.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-245","question":"A contract priced at ₹50 lakh is accounted for over time using the cost-to-cost input method. Costs to date are ₹18 lakh and further costs to complete are estimated at ₹12 lakh. How much profit is recognised to date?","options":["₹20 lakh","₹30 lakh","₹12 lakh","₹8 lakh"],"answer":2,"explanation":"Progress = 18 ÷ 30 = 60%. Revenue to date = 60% × 50 = ₹30 lakh; profit = 30 − 18 = ₹12 lakh (60% of the expected ₹20 lakh). ₹30 lakh is the revenue, not the profit; ₹8 lakh applies the 40% still to be done.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-246","question":"A fixed-price contract for ₹40 lakh has incurred costs of ₹25 lakh and needs a further ₹20 lakh to complete. It is 25/45 complete. How much loss is recognised this year?","options":["₹5 lakh","₹2.78 lakh","Nil","₹25 lakh"],"answer":0,"explanation":"Total expected cost ₹45 lakh exceeds the price by ₹5 lakh, so the contract is onerous and the entire expected loss is recognised at once, not in proportion to progress. ₹2.78 lakh spreads the loss by completion (25/45).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-247","question":"Match each overhead with its usual basis of apportionment. (a) Factory rent (b) Canteen expenses (c) Power for machines (d) Insurance of stock. Bases: (1) Number of employees (2) Floor area (3) Value of stock (4) Horsepower × machine hours.","options":["a-2, b-4, c-1, d-3","a-3, b-1, c-4, d-2","a-1, b-2, c-3, d-4","a-2, b-1, c-4, d-3"],"answer":3,"explanation":"Rent follows the space occupied (floor area); canteen cost follows headcount; machine power follows rated horsepower times running hours; stock insurance follows the value of stock held.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-248","question":"Kaizen costing aims at:","options":["Setting a cost ceiling at the design stage from a target price","Charging overheads through activities","Small, continuous cost reductions during the production phase","Comparing actual costs with predetermined standards each month"],"answer":2,"explanation":"Kaizen costing seeks steady incremental savings once a product is in production. Fixing allowable cost at the design stage is target costing; overheads through activities is ABC; comparing against standards is standard costing.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-249","question":"A bottleneck machine has 10,000 hours a year and total factory costs (all costs other than materials) are ₹6,00,000. Product B sells at ₹165, uses ₹60 of materials and needs 1.5 bottleneck hours. What is B's throughput accounting ratio?","options":["1.00","1.17","1.75","0.86"],"answer":1,"explanation":"Throughput per bottleneck hour = (165 − 60) ÷ 1.5 = ₹70. Factory cost per bottleneck hour = 6,00,000 ÷ 10,000 = ₹60. TA ratio = 70 ÷ 60 = 1.17, so B covers its share of factory costs. 1.75 forgets to divide by the 1.5 hours; 0.86 inverts the ratio.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-250","question":"5,000 debentures of ₹100, redeemable at a 10% premium, are redeemed by converting them into equity shares of ₹10 each issued at ₹12.50. How many shares are issued?","options":["44,000","40,000","55,000","50,000"],"answer":0,"explanation":"Amount due = 5,000 × 110 = ₹5,50,000; shares = 5,50,000 ÷ 12.50 = 44,000. Ignoring the redemption premium gives 40,000; issuing at par gives 55,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
];

